const VFM=new Map();let VFB=false;
function vfur(t){if(!VFB){VFB=true;for(const v of V)if(!VFM.has(v.w))VFM.set(v.w,v.r)}
  const r=VFM.get(t),KJ=/[一-龥々]/;if(!r||!KJ.test(t))return "";
  let a=t,b=r,pre="",suf="";
  while(a&&b&&a[0]===b[0]&&!KJ.test(a[0])){pre+=a[0];a=a.slice(1);b=b.slice(1)}
  while(a&&b&&a.slice(-1)===b.slice(-1)&&!KJ.test(a.slice(-1))){suf=a.slice(-1)+suf;a=a.slice(0,-1);b=b.slice(0,-1)}
  return a&&b?rb(pre+"{"+a+"|"+b+"}"+suf):""}
const PB=()=>`<p class="count crumb"><a href="#practice">← Practice</a></p>`;
const fr=t=>FUR[t]?rb(FUR[t]):(vfur(t)||esc(t));
const frd=(p,f)=>{if(f&&typeof f==="string"&&plainR(f).replace(/\s/g,"")===String(p).replace(/\s/g,""))return rb(f);return fr(p)};
const FB=()=>`<button class="linkbtn furibtn" data-furi="1">${store.set.furi?"Hide furigana":"Show furigana"}</button>`;
const FGUIDE=`<details class="fguide"><summary>What do these form names mean?</summary><div class="fg-grid">
<div><b>Plain form</b><span lang="ja">食べる・食べない・食べた・食べなかった</span><small>dictionary-style forms without です/ます</small></div>
<div><b>ます-stem</b><span lang="ja">食べ(ます)・書き(ます)・し(ます)</span><small>the part before ます</small></div>
<div><b>て-form</b><span lang="ja">食べて・書いて・して</span><small>the “and / -ing” form</small></div>
<div><b>ない-form</b><span lang="ja">食べない・書かない・しない</span><small>plain negative</small></div>
<div><b>Volitional</b><span lang="ja">食べよう・書こう・しよう</span><small>“let’s / I’ll” form</small></div>
<div><b>Potential</b><span lang="ja">食べられる・書ける・できる</span><small>“can do” form</small></div>
<div><b>い-adj stem</b><span lang="ja">高(い) → 高</span><small>drop the final い</small></div>
<div><b>な-adj + な / Noun + の</b><span lang="ja">静かな・学生の</span><small>the form used before nouns</small></div>
</div></details>`;
const mistakeHTML=t=>esc(t).replace(/✗\s*([^→.;]+)/g,'<span class="wrong">✗ $1</span>').replace(/✓\s*([^.;,()]+)/g,'<span class="right">✓ $1</span>');
function connTable(g){
  const gx=GX[+g.id.slice(1)];
  return `<div class="ctable" role="table" aria-label="How ${esc(g.p)} connects">${gx[1].map(([cls,items])=>`<div class="crow" role="row"><div class="ccls" role="rowheader">${cls}</div><div class="citems" role="cell">${items?items.map(([f,l])=>`<span class="cform"><span class="jp-s" lang="ja">${rb(f)}</span>${l?`<small>${esc(l)}</small>`:""}</span>`).join(""):`<span class="cno">✗ not used</span>`}</div></div>`).join("")}</div>`+FGUIDE;
}
function examplesHTML(g){
  const gx=GX[+g.id.slice(1)];
  return `<ol class="gex">${gx[2].map(([j,e,a],i)=>{const pl=plainR(j);const key0=a||g.a,key=(i===0||pl.includes(key0))?key0:key0.replace(/だ$/,""),from=i===0?g.s.indexOf("＿＿"):pl.indexOf(key);
    return `<li><div class="line"><p class="jp" lang="ja">${rb(j,from,from>=0?key.length:0)}</p>${spkBtn(pl)}</div><p class="tr">${esc(e)}</p></li>`}).join("")}</ol>`;
}
function lessonHTML(g,full=true){
  const gx=GX[+g.id.slice(1)];
  const gc=GC[+g.id.slice(1)];
  return `<p class="gnote">${esc(gx[0])}</p>
  <p class="gmini"><b>⚖️ Don’t confuse:</b> <span lang="ja">${esc(gc[0])}</span></p>
  <p class="gmini"><b>⚠️ Mistake:</b> <span lang="ja">${mistakeHTML(gc[1])}</span></p>
  ${full?`<h4 class="gh">How to connect</h4>${connTable(g)}`:""}
  <div class="gh-row"><h4 class="gh">Examples</h4><button class="linkbtn" data-furi="1">${store.set.furi?"Hide furigana":"Show furigana"}</button></div>
  ${examplesHTML(g)}`;
}
const CATS=[...new Set(G.map(g=>g.cat))];
const catTone=c=>"t"+(CATS.indexOf(c)%5);
const GL={list:[],i:0};
function openGrammar(id,keep){
  if(!keep||!GL.list.includes(id)){GL.list=(view==="grammar"?filtered("grammar"):G).map(x=>x.id);if(!GL.list.includes(id))GL.list=G.map(x=>x.id)}
  GL.i=GL.list.indexOf(id);
  const g=BYID[id],gx=GX[+id.slice(1)],known=store.k[id]==="known",same=dlg.open&&dlg.dataset.gid===id;
  const y=same?dlg.querySelector(".gm-body")?.scrollTop||0:0;
  dlg.dataset.id="";dlg.dataset.mode="g";dlg.dataset.gid=id;dlg.className="wide";
  dlg.innerHTML=`<div class="gm">
    <header class="gm-head"><div class="gm-meta"><span class="gcat ${catTone(g.cat)}">${esc(g.cat)}</span><span class="count">${GL.i+1} / ${GL.list.length}</span></div><button class="icon-btn" data-close aria-label="Close">✕</button></header>
    <div class="gm-body">
      <div class="gm-title"><h2 lang="ja">${esc(g.p)}</h2><p class="gm-mean">${esc(g.m)}</p><p class="gm-form"><span>Form</span> <b lang="ja">${esc(g.f)}</b></p></div>
      <section class="gsec"><h3><span class="gi" aria-hidden="true">💡</span>What it means</h3><p class="gnote">${esc(gx[0])}</p></section>
      <div class="gtips"><section class="gtip gtip-c"><h3><span aria-hidden="true">⚖️</span>Don’t confuse with</h3><p lang="ja">${esc(GC[+id.slice(1)][0])}</p></section><section class="gtip gtip-m"><h3><span aria-hidden="true">⚠️</span>Common mistake</h3><p lang="ja">${mistakeHTML(GC[+id.slice(1)][1])}</p></section></div>
      <section class="gsec"><h3><span class="gi" aria-hidden="true">🔗</span>How to connect</h3>${connTable(g)}</section>
      <section class="gsec"><div class="gh-row"><h3><span class="gi" aria-hidden="true">📝</span>Examples</h3><button class="linkbtn" data-furi="1">${store.set.furi?"Hide furigana":"Show furigana"}</button></div>${examplesHTML(g)}</section>
    </div>
    <footer class="gm-foot">
      <button class="btn" data-gnav="-1" ${GL.i===0?"disabled":""} aria-label="Previous grammar point">←<span class="hide-s"> Previous</span></button>
      <div class="gm-acts"><button class="btn ${known?"known":""}" data-gtoggle="${id}">${known?"Learned ✓":"Mark as learned"}</button>${g.tiles.length>2?`<button class="btn" data-sent="${id}">Build<span class="hide-s"> a sentence</span></button>`:""}</div>
      <button class="btn primary" data-gnav="1" ${GL.i>=GL.list.length-1?"disabled":""} aria-label="Next grammar point"><span class="hide-s">Next </span>→</button>
    </footer></div>`;
  if(!dlg.open)dlg.showModal();
  const b=dlg.querySelector(".gm-body");if(b)b.scrollTop=y;
}
/* ============ VOCAB FLASHCARD POPUP ============ */
const VF={list:[],i:0,flip:false};
function openVocab(id){
  const list=filtered("vocab").map(x=>x.id);VF.list=list;VF.i=Math.max(0,list.indexOf(id));VF.flip=false;paintVocab();
}
function paintVocab(){
  const id=VF.list[VF.i],x=BYID[id];if(!x)return;
  dlg.dataset.id="";dlg.dataset.mode="v";dlg.className="";
  dlg.innerHTML=`<div class="dlg" style="position:relative"><button class="icon-btn dlg-x" data-close aria-label="Close">✕</button>
    <p class="count" style="margin:0">Word ${VF.i+1} of ${VF.list.length.toLocaleString()} · ${status(id)==="known"?"✓ Got it":status(id)==="again"?"Still learning":"Not marked"}</p>
    <div class="flash ${VF.flip?"flipped":""}" data-vflip="1" role="button" tabindex="0" aria-label="Flip card">
      <div class="flash-in"><div class="face front" aria-hidden="${VF.flip}">${front("vocab",x)}</div><div class="face back" aria-hidden="${!VF.flip}">${back("vocab",x)}</div></div>
    </div>
    <div class="deck-btns"><button class="btn" data-vnav="-1" ${VF.i===0?"disabled":""} aria-label="Previous word">←</button><button class="btn again" data-vmark="again">Still learning</button><button class="btn known" data-vmark="known">Got it</button><button class="btn" data-vnav="1" ${VF.i>=VF.list.length-1?"disabled":""} aria-label="Next word">→</button></div>
    <p class="kbd">Space flips · 1 still learning · 2 got it · arrows move</p></div>`;
  if(!dlg.open)dlg.showModal();
  dlg.querySelector(".flash")?.focus();
}

/* ============ SECTION (browse + flashcards) ============ */
function sectionView(sec){
  const st=S[sec],s=SECS[sec];
  const chips=s.chips.map(c=>`<button class="chip" data-cat="${esc(c)}" aria-pressed="${st.cat===c}">${esc(CHIPLABEL[c]||c)} <small>${countFor(sec,c)}</small></button>`).join("");
  const learnedN=s.items.filter(x=>store.srs[x.id]||store.k[x.id]==="known").length;
  const SUB={kanji:`${K.length} kanji from N5 to N3, each with a picture and a one-line story`,vocab:`${V.length.toLocaleString()} words, including workplace terms and keigo`,grammar:`${G.length} grammar points, each with a full lesson and examples`};
  return `<div class="sec-head"><div><h1>${s.title}</h1><p class="lede">${SUB[sec]}</p></div>
    <div class="seg" role="group" aria-label="View"><button data-mode="browse" aria-pressed="${st.mode==="browse"}">Browse</button><button data-mode="cards" aria-pressed="${st.mode==="cards"}">Flashcards</button></div></div>
    <div class="chips" role="group" aria-label="Filter">${chips}</div>
    ${sec==="kanji"?`<p class="startline">New here? <a href="#dojo">Start with today’s review</a> — it gives you new kanji every day with spaced repetition. This page is for browsing and looking things up.</p><a class="partsbtn" href="#parts"><span lang="ja">亻氵言</span> Parts guide: 32 building blocks with emojis</a>`:""}
    ${sec==="grammar"?`<p class="count" style="margin:-6px 0 14px">Tap any card for the full lesson: how it connects to verbs, い-adjectives, な-adjectives and nouns in every tense, plus 3 examples with furigana.</p>`:""}
    ${(()=>{const t={kanji:"k",vocab:"v",grammar:"g"}[sec];const n=(store.pend&&store.pend[t]||[]).length;return `<p class="count autoline">Auto test: <b>${n} / ${AUTOT[t]}</b> ${AUTON[t]} marked “Got it”. A quick test starts when you reach ${AUTOT[t]}.</p>`})()}
    <div id="secbody">${st.mode==="browse"?browseView(sec):deckView(sec)}</div>`
}
function browseView(sec){
  const st=S[sec],all=filtered(sec),items=all.slice(0,st.limit);
  const ph=sec==="kanji"?"Search kanji, meaning or reading":sec==="vocab"?"Search word, reading or meaning":"Search pattern or meaning";
  let list="";
  if(!all.length)list=`<div class="empty">Nothing matches “${esc(st.q)}”. Try another word, or choose All.</div>`;
  else if(sec==="kanji")list=`<div class="tiles">${items.map(k=>`<button class="tile ${status(k.id)}" data-open="${k.id}"><span class="tile-k" lang="ja">${k.c}</span><span class="tile-m">${esc(k.m.split(",")[0])}</span>${tileEmo(k)?`<span class="tscene" aria-hidden="true">${tileEmo(k)}</span>`:""}</button>`).join("")}</div>`;
  else if(sec==="vocab")list=`<p class="count" style="margin:-6px 0 10px">Tap any word to open it as a flashcard.</p><div class="rows">${items.map((v,i)=>`${st.cat==="N3"&&!st.q&&i===0&&PRO.has(v.cat)?`<div class="vsec"><b>💼 Professional Japanese</b><span>Workplace words, business phrases and keigo you’ll use at work</span></div>`:""}${st.cat==="N3"&&!st.q&&i>0&&PRO.has(items[i-1].cat)&&!PRO.has(v.cat)?`<div class="vsec"><b>📘 N3 word list</b><span>The official-level N3 vocabulary</span></div>`:""}<div class="row ${status(v.id)}" data-vopen="${v.id}">${spkBtn(v.w)}<span class="w" lang="ja">${esc(v.w)}</span><span class="r" lang="ja">${esc(v.r)}</span><span class="m">${esc(v.m)}${PRO.has(v.cat)?` <span class="vtag">${esc(v.cat)}</span>`:""}</span><button class="icon-btn mk" data-toggle="${v.id}" aria-pressed="${store.k[v.id]==="known"}" aria-label="Mark ${esc(v.w)} as learned">${CHK}</button></div>`).join("")}</div>`;
  else list=`<div class="gcards">${items.map(g=>{const ex=plainR(GX[+g.id.slice(1)][2][0][0]);const st=status(g.id);
    return `<button class="gcard ${st}" data-gopen="${g.id}"><span class="gcard-top"><span class="gcat ${catTone(g.cat)}">${esc(g.cat)}</span>${st==="known"?'<span class="gdone" aria-label="Learned">✓ Learned</span>':""}</span><span class="gcard-p" lang="ja">${esc(g.p)}</span><span class="gcard-m">${esc(g.m)}</span><span class="gcard-ex" lang="ja">${esc(ex)}</span></button>`}).join("")}</div>`;
  const more=all.length>items.length?`<div class="more"><button class="btn" data-act="more">Show ${Math.min(PAGE,all.length-items.length)} more</button><span class="count">Showing ${items.length} of ${all.length.toLocaleString()}</span></div>`:"";
  return `<div class="tools"><input class="search" type="search" id="q" placeholder="${ph}" value="${esc(st.q)}" aria-label="${ph}"><span class="count">${all.length.toLocaleString()} items</span><span class="legend"><span class="lk">Got it</span><span class="la">Still learning</span></span></div>${list}${more}`;
}
function buildDeck(sec){const st=S[sec];let it=filtered(sec);if(st.onlyNew)it=it.filter(x=>store.k[x.id]!=="known");st.deck=it.map(x=>x.id);st.i=0;st.flip=false}
function front(sec,x){
  if(sec==="kanji")return `${lvlBadge(x.lvl)}<div class="sq"><span lang="ja">${x.c}</span></div><p class="hint">Tap to see the meaning and memory hook</p>`;
  if(sec==="vocab")return `${lvlBadge(x.lvl)}${x.cat?`<span class="cat">${esc(x.cat)}</span>`:""}<div class="word" lang="ja">${esc(x.w)}</div><p class="hint">Tap to see the reading and meaning</p>`;
  return `<span class="cat">${esc(x.cat)}</span><div class="pat" lang="ja">${esc(x.p)}</div><p class="hint">Tap to see the meaning and an example</p>`;
}
const bold=t=>esc(t).replace(/\*\*(.+?)\*\*/g,"<b>$1</b>");
function kanjiPic(x,size){
  const strokes=SD[x.c]||[];const col={};x.comp.forEach((p,i)=>p[2].forEach(n=>col[n]=i));
  if(!strokes.length)return `<div class="kpic" lang="ja" style="width:${size}px;height:${size}px;display:grid;place-items:center;font-size:${Math.round(size*.78)}px;line-height:1">${x.c}</div>`;
  return `<svg class="kpic" viewBox="0 0 109 109" width="${size}" height="${size}" role="img" aria-label="${x.c} with its parts in color">${strokes.map((d,i)=>`<path d="${d}" class="pc${col[i]===undefined?"x":col[i]%5}"/>`).join("")}</svg>`;
}
function equation(x){
  const parts=x.comp.length?x.comp.map(([ch,n],i)=>`<span class="part"><i class="sw pc${i%5}"></i>${EMO[n]?`<span class="emo">${EMO[n]}</span>`:""}<b lang="ja">${esc(ch)}</b>${n?` <span class="pname">${esc(n)}</span>`:""}</span>`)
    :x.parts.map(([ch,n])=>`<span class="part">${EMO[n]?`<span class="emo">${EMO[n]}</span>`:""}<b lang="ja">${esc(ch)}</b> <span class="pname">${esc(n)}</span></span>`);
  if(!parts.length)return "";
  return `<div class="eq">${parts.join('<span class="op">+</span>')}<span class="op">=</span><span class="part res"><b lang="ja">${x.c}</b> <span class="pname">${esc(x.m.split(",")[0])}</span></span></div>`;
}
const GS={c:null,busy:false,err:"",edit:null};
function storyHTML(t,x){let h=bold(t);x.comp.forEach(([ch],i)=>{h=h.split("("+esc(ch)+")").join(`<span class="spart"><i class="sw pc${i%5}"></i><b lang="ja">${esc(ch)}</b></span>`)});return h}
/* ============ SOUND FAMILIES ============ */
const SFAM=[{"k":"青","r":"セイ","ka":1,"ko":"セイ、ショウ","m":[{"c":"清","a":0,"o":"セイ、ショウ","x":0},{"c":"晴","a":1,"o":"セイ","x":0},{"c":"静","a":1,"o":"セイ、ジョウ","x":0},{"c":"精","a":1,"o":"セイ、ショウ","x":0},{"c":"請","a":0,"o":"セイ、シン","x":0},{"c":"情","a":1,"o":"ジョウ","x":0}]},{"k":"寺","r":"ジ","ka":0,"ko":"","m":[{"c":"持","a":1,"o":"ジ","x":0},{"c":"時","a":1,"o":"ジ","x":0},{"c":"詩","a":0,"o":"シ","x":0},{"c":"侍","a":0,"o":"ジ、シ","x":0},{"c":"待","a":1,"o":"タイ","x":1},{"c":"特","a":1,"o":"トク","x":1},{"c":"等","a":1,"o":"トウ","x":1}]},{"k":"交","r":"コウ","ka":1,"ko":"コウ","m":[{"c":"校","a":1,"o":"コウ、キョウ","x":0},{"c":"効","a":0,"o":"コウ","x":0},{"c":"郊","a":0,"o":"コウ","x":0},{"c":"絞","a":0,"o":"コウ","x":0},{"c":"較","a":0,"o":"カク、コウ","x":0}]},{"k":"可","r":"カ","ka":0,"ko":"","m":[{"c":"河","a":0,"o":"カ","x":0},{"c":"何","a":1,"o":"カ","x":0},{"c":"歌","a":1,"o":"カ","x":0}]},{"k":"反","r":"ハン","ka":1,"ko":"ハン、ホン、タン、ホ","m":[{"c":"坂","a":0,"o":"ハン","x":0},{"c":"板","a":0,"o":"ハン、バン","x":0},{"c":"飯","a":1,"o":"ハン","x":0},{"c":"版","a":0,"o":"ハン","x":0},{"c":"販","a":1,"o":"ハン","x":0},{"c":"返","a":1,"o":"ヘン","x":1}]},{"k":"古","r":"コ","ka":1,"ko":"コ","m":[{"c":"固","a":0,"o":"コ","x":0},{"c":"故","a":0,"o":"コ","x":0},{"c":"湖","a":0,"o":"コ","x":0},{"c":"個","a":1,"o":"コ","x":0},{"c":"苦","a":1,"o":"ク","x":1},{"c":"居","a":1,"o":"キョ、コ","x":0}]},{"k":"方","r":"ホウ","ka":1,"ko":"ホウ","m":[{"c":"放","a":1,"o":"ホウ","x":0},{"c":"訪","a":1,"o":"ホウ","x":0},{"c":"防","a":0,"o":"ボウ","x":0},{"c":"房","a":0,"o":"ボウ","x":0},{"c":"妨","a":0,"o":"ボウ","x":0}]},{"k":"官","r":"カン","ka":1,"ko":"カン","m":[{"c":"管","a":1,"o":"カン","x":0},{"c":"館","a":1,"o":"カン","x":0}]},{"k":"化","r":"カ","ka":1,"ko":"カ、ケ","m":[{"c":"花","a":1,"o":"カ、ケ","x":0},{"c":"貨","a":0,"o":"カ","x":0},{"c":"靴","a":1,"o":"カ","x":0}]},{"k":"羊","r":"ヨウ","ka":0,"ko":"","m":[{"c":"洋","a":1,"o":"ヨウ","x":0},{"c":"養","a":0,"o":"ヨウ、リョウ","x":0},{"c":"様","a":1,"o":"ヨウ","x":0}]},{"k":"才","r":"サイ・ザイ","ka":1,"ko":"サイ","m":[{"c":"材","a":0,"o":"ザイ","x":0},{"c":"財","a":1,"o":"ザイ、サイ、ゾク","x":0},{"c":"在","a":1,"o":"ザイ","x":0}]},{"k":"己","r":"キ","ka":0,"ko":"","m":[{"c":"記","a":1,"o":"キ","x":0},{"c":"紀","a":0,"o":"キ","x":0},{"c":"起","a":1,"o":"キ","x":0},{"c":"配","a":1,"o":"ハイ","x":1}]},{"k":"及","r":"キュウ","ka":0,"ko":"","m":[{"c":"級","a":0,"o":"キュウ","x":0},{"c":"吸","a":1,"o":"キュウ","x":0},{"c":"急","a":1,"o":"キュウ","x":0}]},{"k":"求","r":"キュウ","ka":1,"ko":"キュウ","m":[{"c":"球","a":1,"o":"キュウ","x":0},{"c":"救","a":0,"o":"キュウ","x":0}]},{"k":"共","r":"キョウ","ka":1,"ko":"キョウ","m":[{"c":"供","a":1,"o":"キョウ、ク、クウ、グ","x":0}]},{"k":"正","r":"セイ・ショウ","ka":1,"ko":"セイ、ショウ","m":[{"c":"政","a":1,"o":"セイ、ショウ","x":0},{"c":"証","a":0,"o":"ショウ","x":0},{"c":"症","a":0,"o":"ショウ","x":0},{"c":"整","a":0,"o":"セイ","x":0}]},{"k":"半","r":"ハン","ka":1,"ko":"ハン","m":[{"c":"判","a":1,"o":"ハン、バン","x":0},{"c":"伴","a":0,"o":"ハン、バン","x":0}]},{"k":"皮","r":"ヒ","ka":0,"ko":"","m":[{"c":"彼","a":1,"o":"ヒ","x":0},{"c":"疲","a":1,"o":"ヒ","x":0},{"c":"被","a":0,"o":"ヒ","x":0},{"c":"破","a":1,"o":"ハ","x":1},{"c":"波","a":0,"o":"ハ","x":1}]},{"k":"非","r":"ヒ","ka":1,"ko":"ヒ","m":[{"c":"悲","a":1,"o":"ヒ","x":0},{"c":"排","a":0,"o":"ハイ","x":1}]},{"k":"生","r":"セイ・ショウ","ka":1,"ko":"セイ、ショウ","m":[{"c":"性","a":1,"o":"セイ、ショウ","x":0},{"c":"星","a":0,"o":"セイ、ショウ","x":0},{"c":"姓","a":0,"o":"セイ、ショウ","x":0}]},{"k":"安","r":"アン","ka":1,"ko":"アン","m":[{"c":"案","a":1,"o":"アン","x":0}]},{"k":"相","r":"ソウ","ka":1,"ko":"ソウ、ショウ","m":[{"c":"想","a":1,"o":"ソウ、ソ","x":0}]},{"k":"亡","r":"ボウ","ka":1,"ko":"ボウ、モウ","m":[{"c":"望","a":1,"o":"ボウ、モウ","x":0},{"c":"忘","a":1,"o":"ボウ","x":0},{"c":"忙","a":1,"o":"ボウ、モウ","x":0}]},{"k":"丁","r":"チョウ","ka":0,"ko":"","m":[{"c":"町","a":1,"o":"チョウ","x":0},{"c":"庁","a":0,"o":"チョウ、テイ","x":0},{"c":"頂","a":1,"o":"チョウ","x":0},{"c":"停","a":0,"o":"テイ","x":0},{"c":"訂","a":0,"o":"テイ","x":0}]}];
const SFX={};SFAM.forEach(f=>{if(f.ka)SFX[f.k]=f;f.m.forEach(m=>{if(m.a)SFX[m.c]=f})});
const sfChip=(c,o,cls,cur)=>`<span class="sfc ${cls||""}${c===cur?" me":""}"><b lang="ja">${c}</b><small lang="ja">${esc(o)}</small></span>`;
function sfBox(x){
  const f=SFX[x.c];if(!f)return "";
  const main=f.m.filter(m=>!m.x),exc=f.m.filter(m=>m.x);
  return `<div class="sfam"><div class="sf-h">🔊 Sound family <small>· the piece <b lang="ja">${f.k}</b> usually gives the sound <b lang="ja">${esc(f.r)}</b></small></div>
  <div class="sf-row">${f.ka?sfChip(f.k,f.ko,"",x.c):""}${main.map(m=>sfChip(m.c,m.o,m.a?"":"dim",x.c)).join("")}</div>
  ${exc.length?`<p class="sf-ex">Exceptions: ${exc.map(m=>`<span lang="ja">${m.c} ${esc(m.o)}</span>`).join(" · ")}</p>`:""}
  ${main.some(m=>!m.a)?`<p class="sf-n">Faded kanji are not in this app yet.</p>`:""}</div>`;
}
function makeSF(f){
  const mem=[...(f.ka?[{c:f.k}]:[]),...f.m.filter(m=>m.a&&!m.x)];
  const show=shuffle(mem).slice(0,3);
  const others=[...new Set(SFAM.map(g=>g.r).filter(r=>r!==f.r))];
  return {x:{id:"sf"+f.k,c:f.k,ex:[],m:""},type:"sf",sf:f,ask:"These kanji share a sound piece. Which reading do they usually share?",prompt:`<div class="q-word" lang="ja">${show.map(m=>m.c).join(" ")}</div>`,ans:f.r,opts:shuffle([f.r,...shuffle(others).slice(0,3)]),jp:true};
}
function hook(x,lite){
  const mine=store.stories[x.c];
  const story=mine?mine.s:x.story,scene=mine?mine.e:x.scene;
  let body;
  if(GS.edit===x.c){
    body=`<label class="count">Picture (emoji)<input class="search st-e" id="st-e" value="${esc(scene||"")}" maxlength="24"></label>
      <label class="count">Your story<textarea class="st-s" id="st-s" rows="4">${esc(story||"")}</textarea></label>
      <div class="acts-l"><button class="btn primary" data-stsave="${x.c}">Save story</button><button class="btn" data-stcancel="1">Cancel</button></div>`;
  }else{
    body=`${scene&&!lite?`<div class="scene" aria-hidden="true">${esc(scene)}</div>`:""}
      ${story?`<div class="st-label">Memory story <small>· a trick to remember it, not the real origin</small></div><p class="st">${storyHTML(story,x)}</p>`:`<p class="st muted">No story yet — link the colored parts into one scene that means “${esc(x.m.split(",")[0])}”.</p>`}
      ${GS.c===x.c&&GS.busy?`<p class="count">✨ Writing a story…</p>`:GS.c===x.c&&GS.err?`<p class="count err">${esc(GS.err)}</p>`:""}
      <div class="st-acts">${RP.avail!==false?`<button class="linkbtn" data-stgen="${x.c}" ${GS.busy?"disabled":""}>✨ ${story?"New story":"Create a story"}</button>`:""}<button class="linkbtn" data-stedit="${x.c}">✏️ ${mine?"Edit my story":"Write my own"}</button>${mine?`<button class="linkbtn" data-streset="${x.c}">Reset</button>`:""}</div>`;
  }
  const th=TH[x.c]?`<div class="st-label">Tanglish hint</div><p class="st">${esc(TH[x.c])}</p>`:"";
  return `<div class="mem">${kanjiPic(x,96)}<div class="mem-r">${lite?"":equation(x)}${body}${th}</div></div>`;
}
function refreshKanji(){if(dlg.open&&dlg.dataset.id)openKanji(dlg.dataset.id,true);else render()}
async function genStory(c){
  const x=KBYC[c];if(!x||GS.busy)return;
  if(!SAMPLE){GS.c=c;GS.err="Story writing needs Claude, which is only available when this page is opened inside claude.ai.";refreshKanji();return}
  Object.assign(GS,{c,busy:true,err:""});refreshKanji();
  const parts=(x.comp.length?x.comp.map(p=>`${p[0]} (${p[1]||"shape"})`):x.parts.map(p=>`${p[0]} (${p[1]})`)).join(", ");
  const prompt=`Write a memorable mnemonic story to help a JLPT N3 learner remember the kanji ${x.c}.
Meaning: ${x.m}
Readings: on ${x.on||"none"}, kun ${x.kun||"none"}
Its visual parts: ${parts}

Rules: 1–3 short sentences, under 55 words, vivid and a little funny, with a concrete scene and a character doing something. Mention every part with its character in parentheses, like "a person (亻)". End by tying the scene to the meaning, with the meaning word(s) in **double asterisks**. Also give 2–4 emoji that picture the scene.
Respond with ONLY JSON: {"story":"...","scene":"emoji"}`;
  try{const r=await SAMPLE.json(prompt,{modelTier:"default",cache:false});
    if(r&&r.story){store.stories[c]={s:String(r.story).slice(0,400),e:String(r.scene||"").slice(0,24),ai:1};save();addXP(1)}
    else GS.err="That story didn’t come through. Try again.";
  }catch(e){GS.err=e&&e.code==="not_granted"?"Story writing was declined. You can still write your own.":e&&e.code==="rate_limited"?"Claude is busy for a moment. Try again shortly.":"Couldn’t write a story just now. Try again."}
  GS.busy=false;refreshKanji();
}
let KMORE=null;
function simpleKanji(x,big){
  const f=formula(x),kw=x.ex.slice(0,2),open=KMORE===x.id;
  return `<div class="sk">
    ${big?`<div class="sk-k" lang="ja">${x.c}</div>`:""}
    <div class="sk-m">${esc(x.m.split(",").slice(0,2).join(","))}</div>
    <div class="sk-r" lang="ja">${x.on?`<span><small>On</small> ${x.on}</span>`:""}${x.kun?`<span><small>Kun</small> ${kun(x.kun)}</span>`:""}</div>
    ${f.emo?`<div class="sc-emo" aria-hidden="true">${f.emo}</div>`:""}
    <p class="sc-line">${f.line}</p>
    ${kw.length?`<div class="sc-words">${kw.map(([w,r,m])=>`<button class="kw" data-speak="${esc(w)}" aria-label="Listen: ${esc(w)}"><b lang="ja">${esc(w)}</b><span lang="ja">${esc(r)}</span><small>${esc(m)}</small></button>`).join("")}</div>`:""}
    ${sfBox(x)}
    <button class="linkbtn sc-morebtn" data-kmore="${x.id}" aria-expanded="${open}">${open?"Hide details":"More: picture, story, readings"}</button>
    ${open?`<div class="sc-more">${hook(x,true)}<dl class="rd"><dt>On</dt><dd lang="ja">${x.on||"—"}</dd><dt>Kun</dt><dd lang="ja">${kun(x.kun)}</dd><dt>Strokes</dt><dd>${(SD[x.c]||[]).length||"—"}</dd></dl></div>`:""}
  </div>`;
}
function kanjiDetail(x,withTitle=true){
  return `${withTitle?`<div class="b-big">${esc(x.m)}</div>`:""}
  <dl class="rd"><dt>On</dt><dd lang="ja">${x.on||"—"}</dd><dt>Kun</dt><dd lang="ja">${kun(x.kun)}</dd><dt>Strokes</dt><dd>${(SD[x.c]||[]).length||"—"}</dd></dl>
  ${sfBox(x)}
  ${hook(x)}
  ${x.ex.length?`<ul class="ex">${x.ex.map(([w,r,m])=>`<li><span class="ew" lang="ja">${esc(w)}</span><span class="er" lang="ja">${esc(r)}</span><span class="em">${esc(m)}</span>${spkBtn(w)}</li>`).join("")}</ul>`:""}`;
}
function back(sec,x){
  if(sec==="kanji")return simpleKanji(x,true);
  if(sec==="vocab")return `<div class="word" lang="ja" style="font-family:var(--mincho);font-weight:700;font-size:30px">${esc(x.w)}</div><div class="b-read" lang="ja">${esc(x.r)}</div><div class="b-big">${esc(x.m)}</div><div>${spkBtn(x.w)}</div>`;
  return `<div class="b-big">${esc(x.m)}</div><p class="form"><b>Form:</b> <span lang="ja">${esc(x.f)}</span></p>${lessonHTML(x,false)}<button class="btn" data-glesson="${x.id}">Full lesson: how it connects</button>`;
}
function deckView(sec){
  const st=S[sec];if(!st.deck)buildDeck(sec);
  const top=`<div class="deck-top"><label class="toggle"><input type="checkbox" id="onlynew" ${st.onlyNew?"checked":""}> Only cards I’m still learning</label><button class="btn" data-act="shuffle">Shuffle</button></div>`;
  if(!st.deck.length)return `<div class="deck">${top}<div class="empty">${st.onlyNew?"You’ve marked every card in this set as learned. Turn off the filter to review them all.":"No cards in this set."}</div></div>`;
  if(st.i>=st.deck.length){
    const again=st.deck.filter(id=>store.k[id]==="again").length;
    return `<div class="deck">${top}<div class="done"><div class="big" lang="ja">完</div><h2>You went through ${st.deck.length} cards</h2><p class="lede" style="margin:0 auto">${again?`${again} still need practice.`:"Every card in this round is marked as learned."}</p>
    <div class="acts">${again?`<button class="btn primary" data-act="againonly">Study the ${again} again</button>`:""}<button class="btn" data-act="restart">Start over</button><a class="btn" href="#quiz" style="text-decoration:none">Take a quiz</a></div></div></div>`;
  }
  const x=BYID[st.deck[st.i]];
  return `<div class="deck">${top}
    <div class="flash ${st.flip?"flipped":""}" data-act="flip" role="button" tabindex="0" aria-label="Flip card">
      <div class="flash-in"><div class="face front" aria-hidden="${st.flip}">${front(sec,x)}</div><div class="face back" aria-hidden="${!st.flip}">${back(sec,x)}</div></div>
    </div>
    <div class="deck-btns">
      <button class="btn" data-act="prev" ${st.i===0?"disabled":""} aria-label="Previous card">←</button>
      <button class="btn again" data-act="again">Still learning</button>
      <button class="btn known" data-act="known">Got it</button>
      <button class="btn" data-act="next" aria-label="Next card">→</button>
    </div>
    <p class="kbd">Card ${st.i+1} of ${st.deck.length.toLocaleString()} · Space flips · 1 still learning · 2 got it · arrows move</p>
  </div>`;
}
const KL={list:[],i:0};
function openKanji(id,keep){
  if(!keep||!KL.list.includes(id)){KL.list=(view==="kanji"?filtered("kanji"):K).map(k=>k.id);if(!KL.list.includes(id))KL.list=K.map(k=>k.id)}
  KL.i=KL.list.indexOf(id);
  const x=BYID[id],f=formula(x),kw=x.ex.slice(0,3);
  dlg.dataset.id=id;dlg.dataset.mode="k";dlg.className="kwide";
  dlg.innerHTML=`<div class="dlg" style="position:relative"><button class="icon-btn dlg-x" data-close aria-label="Close">✕</button>
    <div class="sk-head sk-top"><button class="icon-btn" data-knav="-1" ${KL.i===0?"disabled":""} aria-label="Previous kanji">←</button>${lvlBadge(x.lvl)}<span class="count">${KL.i+1} / ${KL.list.length.toLocaleString()}</span><button class="icon-btn" data-knav="1" ${KL.i>=KL.list.length-1?"disabled":""} aria-label="Next kanji">→</button></div>
    <div class="kd"><div class="kd-l sk">
      <div class="sk-k" lang="ja">${x.c}</div>
      <div class="sk-m">${esc(x.m.split(",").slice(0,2).join(","))}</div>
      <div class="sk-r" lang="ja">${x.on?`<span><small>On</small> ${x.on}</span>`:""}${x.kun?`<span><small>Kun</small> ${kun(x.kun)}</span>`:""}</div>
      ${f.emo?`<div class="sc-emo" aria-hidden="true">${f.emo}</div>`:""}
      <p class="sc-line">${f.line}</p></div>
    <div class="kd-r">
      ${kw.length?`<div class="st-label">Example words</div><div class="sc-words">${kw.map(([w,r,m])=>`<button class="kw" data-speak="${esc(w)}" aria-label="Listen: ${esc(w)}"><b lang="ja">${esc(w)}</b><span lang="ja">${esc(r)}</span><small>${esc(m)}</small></button>`).join("")}</div>`:""}
      ${sfBox(x)}
      <div class="kd-story">${hook(x,true)}</div></div></div>
    <div class="sk-acts"><button class="btn again" data-mark="again" data-id="${id}">Still learning</button><button class="btn known" data-mark="known" data-id="${id}">Got it</button><button class="btn" data-dwrite="${x.c}">Write it</button></div>
    <div class="sk-nav"><button class="btn" data-knav="-1" ${KL.i===0?"disabled":""} aria-label="Previous kanji">← Previous</button><button class="btn primary" data-knav="1" ${KL.i>=KL.list.length-1?"disabled":""} aria-label="Next kanji">Next →</button></div></div>`;
  if(!dlg.open)dlg.showModal();
}

/* ============ WRITE (stroke order) ============ */
const W={k:null,mode:"trace",done:0,miss:0,hints:0,lvl:"N3",msg:"",anim:null};
function pickWrite(c){
  let k=c?KBYC[c]:null;
  if(!k){const pool=K.filter(x=>(W.lvl==="All"||x.lvl===W.lvl)&&SD[x.c]);k=pool[Math.floor(Math.random()*pool.length)]}
  Object.assign(W,{k,done:0,miss:0,hints:0,msg:""});
}
function writeView(){
  const k=W.k,n=(SD[k.c]||[]).length;
  const modes=[["watch","Watch"],["trace","Trace"],["recall","From memory"]].map(([m,l])=>`<button data-wmode="${m}" aria-pressed="${W.mode===m}">${l}</button>`).join("");
  return `${PB()}<div class="sec-head"><div><h1>Write kanji</h1><p class="lede">Draw each stroke in order with your finger or mouse.</p></div><div class="seg" role="group" aria-label="Mode">${modes}</div></div>
  <div class="chips">${["N3","N4","N5","Bonus","All"].map(l=>`<button class="chip" data-wlvl="${l}" aria-pressed="${W.lvl===l}">${l==="Bonus"?"Bonus (N2)":l}</button>`).join("")}</div>
  <div class="write">
    <div class="wpad sq"><svg id="wsvg" viewBox="0 0 109 109" aria-label="Writing area for ${k.c}"></svg></div>
    <div class="wside">
      <div class="wtarget"><span class="b-big">${esc(k.m.split(",").slice(0,2).join(","))}</span>${lvlBadge(k.lvl)}</div>
      <dl class="rd"><dt>On</dt><dd lang="ja">${k.on||"—"}</dd><dt>Kun</dt><dd lang="ja">${kun(k.kun)}</dd></dl>
      <div class="wparts">${kanjiPic(k,64)}${equation(k)}</div>
      <p class="wprog" id="wprog">${W.mode==="watch"?`${n} strokes`:`Stroke ${Math.min(W.done+1,n)} of ${n}`}</p>
      <p class="wmsg" id="wmsg" role="status">${esc(W.msg)}</p>
      <div class="acts-l">
        ${W.mode==="watch"?`<button class="btn primary" data-act="wplay">Play again</button><button class="btn" data-wmode="trace">Now trace it</button>`:`<button class="btn" data-act="whint">Show next stroke</button><button class="btn" data-act="wreset">Start over</button>`}
        <button class="btn" data-act="wnext">Next kanji</button>
      </div>
      <form class="wfind" data-act="none" onsubmit="return false"><input class="search" id="wq" placeholder="Type a kanji to practice" maxlength="1" lang="ja" aria-label="Type a kanji to practice"><button class="btn" data-act="wfind">Go</button></form>
    </div>
  </div>`;
}
const NS="http://www.w3.org/2000/svg";
function mountWrite(){
  const svg=document.getElementById("wsvg");if(!svg)return;
  const strokes=SD[W.k.c]||[];
  svg.innerHTML="";
  const gGhost=document.createElementNS(NS,"g"),gInk=document.createElementNS(NS,"g"),gUser=document.createElementNS(NS,"g");
  gGhost.setAttribute("class","ghost");gInk.setAttribute("class","ink");gUser.setAttribute("class","user");
  svg.append(gGhost,gInk,gUser);
  strokes.forEach((d,i)=>{const p=document.createElementNS(NS,"path");p.setAttribute("d",d);p.dataset.i=i;gGhost.append(p)});
  if(W.mode==="recall")gGhost.style.opacity="0";
  if(W.mode==="watch"){gGhost.style.opacity=".35";playStrokes();return}
  for(let i=0;i<W.done;i++)inkStroke(i,false);
  let pts=null,line=null;
  const toLocal=e=>{const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const r=pt.matrixTransform(svg.getScreenCTM().inverse());return[r.x,r.y]};
  svg.onpointerdown=e=>{if(W.done>=strokes.length)return;e.preventDefault();svg.setPointerCapture(e.pointerId);pts=[toLocal(e)];line=document.createElementNS(NS,"polyline");gUser.append(line)};
  svg.onpointermove=e=>{if(!pts)return;pts.push(toLocal(e));line.setAttribute("points",pts.map(p=>p.join(",")).join(" "))};
  svg.onpointerup=svg.onpointercancel=e=>{if(!pts)return;const p=pts;pts=null;line.remove();if(p.length<2)return;judge(p)};
}
function sampleEl(path,n){const L=path.getTotalLength(),o=[];for(let i=0;i<n;i++){const q=path.getPointAtLength(L*i/(n-1));o.push([q.x,q.y])}return o}
function resample(p,n){const d=[0];for(let i=1;i<p.length;i++)d.push(d[i-1]+Math.hypot(p[i][0]-p[i-1][0],p[i][1]-p[i-1][1]));const L=d[d.length-1]||1,o=[];let j=0;
  for(let i=0;i<n;i++){const t=L*i/(n-1);while(j<d.length-2&&d[j+1]<t)j++;const s=d[j+1]-d[j]||1,f=Math.min(1,Math.max(0,(t-d[j])/s));o.push([p[j][0]+(p[j+1][0]-p[j][0])*f,p[j][1]+(p[j+1][1]-p[j][1])*f])}return o}
const meanD=(a,b)=>a.reduce((s,p,i)=>s+Math.hypot(p[0]-b[i][0],p[1]-b[i][1]),0)/a.length;
function judge(p){
  const svg=document.getElementById("wsvg"),exp=svg.querySelector(`.ghost path[data-i="${W.done}"]`);if(!exp)return;
  const N=16,e=sampleEl(exp,N),u=resample(p,N),L=exp.getTotalLength();
  const tol=Math.max(12,Math.min(20,L*.35));
  const fwd=meanD(u,e),rev=meanD(u,e.slice().reverse());
  if(fwd<tol&&Math.hypot(u[0][0]-e[0][0],u[0][1]-e[0][1])<tol*1.5){
    inkStroke(W.done,true);W.done++;W.miss=0;
    const n=(SD[W.k.c]||[]).length;
    if(W.done>=n){const xp=W.hints?3:6;W.msg=`Complete! ${W.k.c} — ${W.k.m.split(",")[0]}`;speak(W.k.ex[0]?W.k.ex[0][0]:W.k.c);addXP(xp)}
    else W.msg="";
  }else{
    W.miss++;
    W.msg=rev<tol?"Right shape, wrong direction. Strokes usually go left→right and top→bottom.":W.miss>=2?"Here’s the stroke — trace it.":"Not quite. Check where this stroke starts.";
    if(W.miss>=2)flashStroke(W.done);
  }
  const n=(SD[W.k.c]||[]).length;
  document.getElementById("wprog").textContent=W.done>=n?`All ${n} strokes done`:`Stroke ${W.done+1} of ${n}`;
  document.getElementById("wmsg").textContent=W.msg;
}
function inkStroke(i,anim){
  const svg=document.getElementById("wsvg"),src=svg.querySelector(`.ghost path[data-i="${i}"]`),ink=svg.querySelector(".ink");
  const p=src.cloneNode();ink.append(p);
  if(anim&&!matchMedia("(prefers-reduced-motion: reduce)").matches){const L=p.getTotalLength();p.style.strokeDasharray=L;p.style.strokeDashoffset=L;p.getBoundingClientRect();p.style.transition="stroke-dashoffset .25s ease-out";p.style.strokeDashoffset=0}
}
function flashStroke(i){
  const svg=document.getElementById("wsvg"),src=svg.querySelector(`.ghost path[data-i="${i}"]`);if(!src)return;
  const p=src.cloneNode();p.setAttribute("class","hintp");svg.append(p);setTimeout(()=>p.remove(),1400);
}
function playStrokes(){
  const svg=document.getElementById("wsvg");if(!svg)return;clearTimeout(W.anim);
  const ink=svg.querySelector(".ink");ink.innerHTML="";const strokes=[...svg.querySelectorAll(".ghost path")];
  const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;
  let i=0;
  const step=()=>{
    if(i>=strokes.length||!document.body.contains(svg))return;
    const p=strokes[i].cloneNode();ink.append(p);
    const s=p.getPointAtLength(0),t=document.createElementNS(NS,"text");t.setAttribute("x",s.x-4);t.setAttribute("y",s.y-2);t.setAttribute("class","snum");t.textContent=i+1;ink.append(t);
    if(!reduce){const L=p.getTotalLength();p.style.strokeDasharray=L;p.style.strokeDashoffset=L;p.getBoundingClientRect();p.style.transition=`stroke-dashoffset ${Math.max(.3,L/90)}s linear`;p.style.strokeDashoffset=0;i++;W.anim=setTimeout(step,Math.max(300,L/90*1000)+150)}
    else{i++;step()}
  };step();
}

/* ============ KANJI BUILDER ============ */
const B={k:null,pool:[],sel:[],wrong:[],tries:0,solved:false,lvl:"N3"};
const PARTPOOL=[...new Map(K.flatMap(k=>k.parts).map(p=>[p[0],p])).values()];
function newBuild(){
  const cands=K.filter(k=>(B.lvl==="All"||k.lvl===B.lvl)&&k.parts.length>=2&&new Set(k.parts.map(p=>p[0])).size===k.parts.length);
  const k=cands[Math.floor(Math.random()*cands.length)];
  const mine=new Set(k.parts.map(p=>p[0]));
  const others=shuffle(PARTPOOL.filter(p=>!mine.has(p[0]))).slice(0,8-k.parts.length);
  Object.assign(B,{k,pool:shuffle([...k.parts,...others]),sel:[],wrong:[],tries:0,solved:false,hint:null});
}
function buildView(){
  const k=B.k,need=k.parts.length;
  const tiles=B.pool.map(([c,n],i)=>{const on=B.sel.includes(i),bad=B.wrong.includes(i),good=B.solved&&k.parts.some(p=>p[0]===c),hn=B.hint===i&&!on;
    return `<button class="ptile ${on?"on":""} ${bad?"no":""} ${good?"yes":""} ${hn?"hint":""}" data-ptile="${i}" aria-pressed="${on}" ${B.solved?"disabled":""}><span class="pc" lang="ja">${c}</span><span class="pn">${esc(n)}</span></button>`}).join("");
  return `${PB()}<div class="sec-head"><div><h1>Kanji builder</h1><p class="lede">Every kanji is built from smaller pieces. Read the meaning, then tap the ${need} pieces that build it.</p></div></div>
  <details class="panel howto" ${B.sel.length||B.tries?"":"open"}><summary><b>How it works</b></summary><ol><li>Read the <b>meaning</b> and <b>readings</b> of the mystery kanji.</li><li>Tap the <b>${need} pieces</b> below that you think build it. Tap a piece again to remove it.</li><li>After ${need} taps it checks itself. <b>Red</b> pieces do not belong, so they are removed and you try again. <b>Green</b> means correct.</li><li>Stuck? Press <b>Hint</b> to light up one correct piece, or <b>Show answer</b>.</li></ol><p class="count">Example: 好 (like) = 女 (woman) + 子 (child).</p></details>
  <div class="chips">${["N3","N4","N5","All"].map(l=>`<button class="chip" data-blvl="${l}" aria-pressed="${B.lvl===l}">${l}</button>`).join("")}</div>
  <div class="bwrap">
    <div class="qcard bcard">
      <div class="sq bsq">${B.solved?`<span lang="ja">${k.c}</span>`:`<span class="qmark" style="${B.sel.length?"font-size:34px!important;letter-spacing:.05em":""}" lang="ja">${B.sel.length?B.sel.map(i=>B.pool[i][0]).concat(Array(Math.max(0,need-B.sel.length)).fill("？")).join("＋"):"?"}</span>`}</div>
      <div><p class="qask">Meaning</p><div class="b-big">${esc(k.m.split(",").slice(0,2).join(","))}</div>
      <p class="qask" style="margin-top:10px">Readings</p><div class="b-read" lang="ja">${readStr(k)}</div>
      <p class="count">${B.sel.length} of ${need} pieces chosen${B.sel.length?" · tap a piece again to remove it":""}</p></div>
    </div>
    ${B.solved?`<div class="fb ok" role="status"><h3>${B.tries<=1?"Built it!":"Got it"}</h3>${hook(k)}${k.ex[0]?`<p class="jp" lang="ja">${esc(k.ex[0][0])}（${esc(k.ex[0][1])}）</p><p>${esc(k.ex[0][2])}</p>`:""}</div>`:B.wrong.length?`<div class="fb no" role="status"><h3>Some pieces don’t belong — the red ones aren’t in this kanji. They were removed, so pick again.</h3></div>`:""}
    <div class="ptiles">${tiles}</div>
    <div class="acts-l">${B.solved?`<button class="btn primary" data-act="bnext">Next kanji</button>`:`<button class="btn" data-act="bclear">Clear</button><button class="btn" data-act="bhint">Hint</button><button class="btn" data-act="breveal">Show answer</button><button class="btn" data-act="bnext">Skip →</button>`}</div>
  </div>`;
}
function tapPart(i){
  if(B.solved)return;
  B.wrong=B.wrong.filter(x=>x!==i);
  if(B.sel.includes(i))B.sel=B.sel.filter(x=>x!==i);else B.sel.push(i);
  const need=B.k.parts.length;
  if(B.sel.length===need){
    B.tries++;
    const want=new Set(B.k.parts.map(p=>p[0]));
    const bad=B.sel.filter(j=>!want.has(B.pool[j][0]));
    if(!bad.length){B.solved=true;speak(B.k.ex[0]?B.k.ex[0][0]:B.k.c);addXP(B.tries===1?4:2)}
    else{B.wrong=bad;B.sel=B.sel.filter(j=>!bad.includes(j))}
  }
  render();
}

/* ============ SENTENCE BUILDER ============ */
const SN={g:null,bank:[],ans:[],state:"",cat:"All",hint:false,tries:0};
function newSentence(id){
  let g=id?BYID[id]:null;
  if(!g){const pool=G.filter(x=>x.tiles.length>2&&(SN.cat==="All"||x.cat===SN.cat));g=pool[Math.floor(Math.random()*pool.length)]}
  const pre=g.s.indexOf("＿＿");let acc=0,ai=0;for(let i=0;i<g.tiles.length;i++){if(acc>=pre){ai=i;break}acc+=g.tiles[i].length}
  const suffix=g.tiles[ai].slice(g.a.length);
  const tiles=g.tiles.map((t,i)=>({t,ok:true,i}));tiles.push({t:g.d[0]+suffix,ok:false,i:-1});
  let bank=shuffle(tiles);let guard=0;while(guard++<10&&bank.filter(x=>x.ok).map(x=>x.t).join("")===g.tiles.join(""))bank=shuffle(tiles);
  Object.assign(SN,{g,bank,ans:[],state:"",hint:false,tries:0,ai});
}
function sentView(){
  const g=SN.g,target=g.tiles.join("");
  const tile=(x,zone,idx)=>{let cls="stile";if(SN.state&&zone==="ans"){cls+=x.t===g.tiles[idx]?" ok":" bad"}
    return `<button class="${cls}" data-stile="${zone}:${idx}" lang="ja" ${SN.state==="solved"?"disabled":""}>${fr(x.t)}</button>`};
  return `${PB()}<div class="sec-head"><div><h1>Sentence builder</h1><p class="lede">Put the words in order. One extra tile doesn’t belong. Tap a tile to move it, or drag to reorder. ${FB()}</p></div></div>
  <div class="chips">${SECS.grammar.chips.map(c=>`<button class="chip" data-scat="${esc(c)}" aria-pressed="${SN.cat===c}">${esc(c)}</button>`).join("")}</div>
  <div class="swrap">
    <div class="qcard" style="text-align:left"><p class="qask">Say this in Japanese</p><div class="q-en">${esc(g.t)}</div>
      <p style="margin:10px 0 0">${SN.hint?`<span class="lvl" lang="ja">${esc(g.p)}</span> <span class="count">${esc(g.m)}</span>`:`<button class="btn" data-act="shint">Show grammar hint</button>`}</p></div>
    <p class="zlabel">Your sentence</p>
    <div class="zone ans" data-zone="ans">${SN.ans.length?SN.ans.map((x,i)=>tile(x,"ans",i)).join(""):`<span class="zhint">Tap tiles below to build the sentence</span>`}</div>
    <p class="zlabel">Word tiles</p>
    <div class="zone bank" data-zone="bank">${SN.bank.map((x,i)=>tile(x,"bank",i)).join("")}</div>
    ${SN.state==="solved"?`<div class="fb ok" role="status"><h3>${SN.tries<=1?"Perfect!":"Correct"}</h3><div class="line"><p class="jp" lang="ja">${filled(g)}</p>${spkBtn(target)}</div><p><b lang="ja">${esc(g.p)}</b>: ${esc(g.m)}</p></div>`:SN.state==="wrong"?`<div class="fb no" role="status"><h3>Not quite — green tiles are in the right place.</h3></div>`:SN.state==="shown"?`<div class="fb no" role="status"><h3>Answer</h3><div class="line"><p class="jp" lang="ja">${filled(g)}</p>${spkBtn(target)}</div><p><b lang="ja">${esc(g.p)}</b>: ${esc(g.m)}</p></div>`:""}
    <div class="acts-l">${SN.state==="solved"||SN.state==="shown"?`<button class="btn primary" data-act="snext">Next sentence</button>`:`<button class="btn primary" data-act="scheck" ${SN.ans.length?"":"disabled"}>Check</button><button class="btn" data-act="sclear">Clear</button><button class="btn" data-act="sshow">Show answer</button>`}</div>
  </div>`;
}
function moveTile(from,idx,to,before){
  const src=from==="ans"?SN.ans:SN.bank,dst=to==="ans"?SN.ans:SN.bank;
  const [x]=src.splice(idx,1);
  let pos=before==null?dst.length:before;
  if(from===to&&before!=null&&idx<before)pos--;
  dst.splice(Math.max(0,Math.min(pos,dst.length)),0,x);
  if(SN.state==="wrong")SN.state="";
  render();
}
function checkSentence(){
  SN.tries++;
  const got=SN.ans.map(x=>x.t).join(""),want=SN.g.tiles.join("");
  if(got===want){SN.state="solved";speak(want);addXP(SN.tries===1?5:3)}else{SN.state="wrong";render()}
}
/* drag to reorder */
let DR=null;
document.addEventListener("pointerdown",e=>{
  const t=e.target.closest(".stile");if(!t||t.disabled)return;
  const [zone,idx]=t.dataset.stile.split(":");
  DR={el:t,zone,idx:+idx,x:e.clientX,y:e.clientY,moved:false,id:e.pointerId};
});
document.addEventListener("pointermove",e=>{
  if(!DR||e.pointerId!==DR.id)return;
  const dx=e.clientX-DR.x,dy=e.clientY-DR.y;
  if(!DR.moved&&Math.hypot(dx,dy)<8)return;
  if(!DR.moved){DR.moved=true;DR.el.classList.add("dragging");try{DR.el.setPointerCapture(e.pointerId)}catch(_){}}
  e.preventDefault();
  DR.el.style.transform=`translate(${dx}px,${dy}px)`;
  DR.el.style.pointerEvents="none";
  document.querySelectorAll(".stile.drop,.zone.drop").forEach(x=>x.classList.remove("drop"));
  const under=document.elementFromPoint(e.clientX,e.clientY);
  const tt=under&&under.closest(".stile"),zz=under&&under.closest(".zone");
  if(tt&&tt!==DR.el)tt.classList.add("drop");else if(zz)zz.classList.add("drop");
  DR.over={tile:tt&&tt!==DR.el?tt.dataset.stile:null,zone:zz?zz.dataset.zone:null};
},{passive:false});
document.addEventListener("pointerup",e=>{
  if(!DR||e.pointerId!==DR.id)return;
  const d=DR;DR=null;
  if(!d.moved){moveTile(d.zone,d.idx,d.zone==="ans"?"bank":"ans",null);return}
  d.el.style.transform="";d.el.style.pointerEvents="";
  const o=d.over||{};
  if(o.tile){const [z,i]=o.tile.split(":");moveTile(d.zone,d.idx,z,+i)}
  else if(o.zone)moveTile(d.zone,d.idx,o.zone,null);
  else render();
});
document.addEventListener("pointercancel",()=>{if(DR){DR=null;render()}});

/* ============ ROLE-PLAY (sample capability) ============ */
const SCEN=[
 {id:"phone-in",k:"電",t:"Taking a call for your boss",d:"You work at みどり商事. A client calls for 佐藤部長, who is out. Take a message politely.",you:"Receptionist at みどり商事",ai:"山田さん, a client from ABC商事",goal:"Explain the manager is out, offer to take a message or have him call back, confirm the caller’s details.",open:"お世話になっております。ABC商事の山田と申します。佐藤部長はいらっしゃいますか。",ph:["申し訳ございません。佐藤はただいま席を外しております。","よろしければ、ご伝言を承りましょうか。","折り返しお電話するよう申し伝えます。","お電話番号をお伺いしてもよろしいでしょうか。"]},
 {id:"phone-out",k:"話",t:"Calling a client to reschedule",d:"You need to move tomorrow’s 2 pm meeting with 田中様 at みらい工業 to Thursday.",you:"Employee at みどり商事",ai:"Receptionist, then 田中様 at みらい工業",goal:"Ask for 田中様, explain the reason, apologize and agree on a new time.",open:"お電話ありがとうございます。みらい工業でございます。",ph:["みどり商事の〇〇と申します。いつもお世話になっております。","恐れ入りますが、田中様はいらっしゃいますか。","明日のお打ち合わせの件でお電話いたしました。","大変申し訳ございませんが、木曜日に変更していただくことは可能でしょうか。"]},
 {id:"late",k:"遅",t:"Apologizing to your boss for being late",d:"You arrived 30 minutes late because the train stopped. Your manager 鈴木部長 asks what happened.",you:"Team member",ai:"鈴木部長, your manager",goal:"Apologize sincerely, explain the reason briefly, and say how you’ll prevent it.",open:"おはよう。今日はずいぶん遅かったね。何かあったの？",ph:["遅れて申し訳ございません。","電車が止まってしまいまして…","ご連絡が遅くなり、大変失礼いたしました。","今後は早めに家を出るようにいたします。"]},
 {id:"help",k:"頼",t:"Asking a senior colleague for help",d:"You don’t understand how to write the monthly sales report. Ask 先輩 高橋さん for help.",you:"Junior employee",ai:"高橋さん, your senior colleague",goal:"Get their attention politely, explain the problem, ask for help, and thank them.",open:"お疲れさま。どうしたの？",ph:["お忙しいところすみません。","少しお時間よろしいでしょうか。","月末の売り上げ報告書の書き方を教えていただけませんか。","ありがとうございます。助かります。"]},
 {id:"visit",k:"訪",t:"Visiting a client’s office",d:"You have a 3 pm appointment with 木村様 at さくら銀行. Introduce yourself at reception.",you:"Sales rep from みどり商事",ai:"Receptionist at さくら銀行",goal:"Give your company and name, state your appointment, and follow the receptionist’s instructions.",open:"いらっしゃいませ。ご用件をお伺いいたします。",ph:["私、みどり商事の〇〇と申します。","15時に木村様とお約束をいただいております。","お取り次ぎをお願いできますでしょうか。","ありがとうございます。失礼いたします。"]},
 {id:"mail-ext",k:"延",t:"Email: asking for a deadline extension",d:"Write an email to 中村様 at ひかり電機 asking to extend Friday’s quote deadline to next Wednesday.",you:"Employee at みどり商事",ai:"中村様, who will reply to your email",goal:"Opening greeting, clear request with reason, apology, closing. Write the whole email in one message.",open:"(Write your email to 中村様. Start with 件名 if you like.)",ph:["件名：お見積もり提出期限について","ひかり電機株式会社　中村様","いつもお世話になっております。みどり商事の〇〇です。","誠に恐縮ですが、提出期限を来週水曜日まで延ばしていただくことは可能でしょうか。","何卒よろしくお願いいたします。"]},
 {id:"mail-decline",k:"断",t:"Email: politely declining an invitation",d:"A client invited you to a product seminar next Tuesday, but you have a business trip. Decline politely.",you:"Employee at みどり商事",ai:"The client who sent the invitation",goal:"Thank them, decline with a reason, show interest for next time, close politely.",open:"(Write your reply declining the seminar invitation.)",ph:["このたびはセミナーのご案内をいただき、ありがとうございます。","あいにく当日は出張の予定が入っており…","誠に残念ではございますが、今回は欠席させていただきます。","またの機会がございましたら、ぜひ参加させていただきたく存じます。"]},
 {id:"interview",k:"面",t:"Job interview",d:"You’re interviewing for an office job at a Japanese company. Answer the interviewer’s questions.",you:"Job applicant",ai:"Interviewer from the HR department",goal:"Introduce yourself, explain your motivation and strengths, ask one question at the end.",open:"本日はお越しいただき、ありがとうございます。では、簡単に自己紹介をお願いいたします。",ph:["〇〇と申します。本日はよろしくお願いいたします。","前職では営業を担当しておりました。","御社を志望した理由は…","一つ質問させていただいてもよろしいでしょうか。"]}
];
const RP={sc:null,turns:[],busy:false,avail:false,err:"",ctl:null,showEn:{},done:false};
let SAMPLE=null;
async function initSample(){
  try{if(!DOJO_CL||typeof DOJO_CL.use!=="function"){RP.avail=false;if(view==="roleplay")render();return}
    SAMPLE=await DOJO_CL.use("sample");RP.avail=!!SAMPLE}catch(e){RP.avail=false}
  if(view==="roleplay")render();
}
function rpView(){
  if(!RP.sc){
    return `${PB()}<div class="sec-head"><div><h1>Workplace role-play</h1><p class="lede">Practice real office situations in Japanese. Claude plays the other person and gives feedback on your keigo after every message.</p></div></div>
    ${RP.avail===false?`<div class="empty">Role-play needs Claude, which is only available when this page is opened inside claude.ai. The useful phrases below still work.</div>`:""}
    <div class="scen">${SCEN.map(s=>`<button class="scard" data-scen="${s.id}"><span class="game-k" lang="ja">${s.k}</span><span><b>${fr(s.t)}</b><br><span class="count">${fr(s.d)}</span></span></button>`).join("")}</div>`;
  }
  const s=RP.sc;
  const msgs=RP.turns.map((m,i)=>{
    if(m.role==="ai")return `<div class="bubble ai"><div class="who">${fr(s.ai)}</div><p class="jp" lang="ja">${frd(m.ja,m.fu)}</p><div class="bub-acts">${spkBtn(m.ja)}${m.en?`<button class="linkbtn" data-en="${i}">${RP.showEn[i]?"Hide English":"Show English"}</button>`:""}</div>${RP.showEn[i]&&m.en?`<p class="tr">${esc(m.en)}</p>`:""}</div>`;
    if(m.role==="note")return `<div class="sysnote">${fr(m.text)}</div>`;
    const f=m.fb;
    return `<div class="bubble me"><div class="who">You</div><p class="jp" lang="ja">${frd(m.text,f&&f.text_furi)}</p></div>
    ${f?`<div class="fbk"><div class="fbk-top"><span class="score" aria-label="Score ${f.score} of 5">${"●".repeat(f.score)}${"○".repeat(5-f.score)}</span><b>${esc(f.verdict||"")}</b></div>
      ${(f.corrections||[]).length?`<ul class="corr">${f.corrections.map(c=>`<li><s lang="ja">${esc(c.wrong)}</s> → <b lang="ja">${frd(c.right,c.right_furi)}</b><br><span class="count">${esc(c.why)}</span></li>`).join("")}</ul>`:""}
      ${f.better?`<p class="count" style="margin:8px 0 2px">More natural:</p><div class="line"><p class="jp" lang="ja">${frd(f.better,f.better_furi)}</p>${spkBtn(f.better)}</div>`:""}</div>`:""}`;
  }).join("");
  return `<div class="rp">
    <div class="rp-head"><button class="btn" data-act="rpback">← Scenarios</button><div><b>${fr(s.t)}</b><div class="count">You: ${fr(s.you)} · Goal: ${fr(s.goal)} · ${FB()}</div></div></div>
    <details class="panel phrases"><summary><b>Useful phrases</b></summary><ul>${s.ph.map(p=>`<li><span lang="ja">${fr(p)}</span> ${spkBtn(p)}</li>`).join("")}</ul></details>
    <div class="msgs" id="msgs">${msgs}${RP.busy?`<div class="sysnote">Thinking…</div>`:""}${RP.err?`<div class="sysnote err">${esc(RP.err)}</div>`:""}${RP.done?`<div class="fb ok"><h3>Scenario complete 🎉</h3><p>Try it again with different wording, or pick another scenario.</p></div>`:""}</div>
    ${RP.avail===false?`<div class="empty">Role-play needs Claude, which is only available when this page is opened inside claude.ai.</div>`:
    `<div class="composer"><textarea id="rpin" rows="${s.id.startsWith("mail")?6:2}" lang="ja" placeholder="${s.id.startsWith("mail")?"Write your email in Japanese…":"Reply in Japanese (English is OK if you’re stuck)"}" ${RP.busy?"disabled":""}></textarea>
    <div class="acts-l">${RP.busy?`<button class="btn" data-act="rpstop">Stop</button>`:`<button class="btn primary" data-act="rpsend">Send</button>`}<button class="btn" data-act="rpreset">Restart</button></div></div>`}
  </div>`;
}
function startScen(id){
  const s=SCEN.find(x=>x.id===id);RP.sc=s;RP.err="";RP.showEn={};RP.done=false;
  RP.turns=s.id.startsWith("mail")?[{role:"note",text:s.open}]:[{role:"ai",ja:s.open,en:""}];
  render();
}
async function rpSend(){
  const box=document.getElementById("rpin");const text=(box&&box.value||"").trim();if(!text||RP.busy)return;
  if(!SAMPLE){RP.avail=false;render();return}
  RP.turns.push({role:"me",text});RP.busy=true;RP.err="";render();
  const s=RP.sc;
  const transcript=RP.turns.filter(t=>t.role!=="note").map(t=>t.role==="ai"?`${s.ai}: ${t.ja}`:`Learner: ${t.text}`).join("\n");
  const prompt=`You are helping a JLPT N3 learner practice Japanese workplace communication through role-play.
Scenario: ${s.d}
The learner plays: ${s.you}
You play: ${s.ai}
Scenario goal for the learner: ${s.goal}

Transcript so far:
${transcript}

Do two things:
1. Give feedback on the learner's LAST message only: grammar, word choice, and especially keigo (尊敬語/謙譲語/丁寧語) appropriate to this business situation. If the learner wrote English or mixed languages, show in "better" how to say it in natural Japanese. Keep explanations short, in English, at an N3 level.
2. Continue the role-play in character with one natural reply in Japanese (use vocabulary an N3 learner can follow; keep it to 1–3 sentences, or a short email reply for email scenarios). If the learner has achieved the scenario goal, wrap up naturally and set done to true.

Respond with ONLY a JSON object, no other text:
{"feedback":{"score":1-5 integer (5 = natural and polite enough for real work),"verdict":"one short English sentence","corrections":[{"wrong":"exact phrase from learner","right":"corrected Japanese","right_furi":"same text with readings","why":"short English reason"}],"better":"the learner's whole message rewritten naturally and politely in Japanese","better_furi":"same text with readings","text_furi":"the learner's exact message with readings added to any kanji"},"reply":{"ja":"your in-character reply in Japanese","furi":"same text with readings","en":"English translation"},"done":true or false}
For every "_furi" field and reply.furi, copy the Japanese text exactly but write each word that contains kanji as {kanji|hiragana reading}, for example {会議|かいぎ}に{出席|しゅっせき}します。 Leave kana, punctuation and English as they are.
Use at most 4 corrections; use an empty list if there are none.`;
  RP.ctl=new AbortController();
  try{
    const r=await SAMPLE.json(prompt,{signal:RP.ctl.signal,cache:false});
    const me=RP.turns[RP.turns.length-1];
    const fb=r&&r.feedback||{};fb.score=Math.max(1,Math.min(5,parseInt(fb.score)||3));me.fb=fb;
    if(r&&r.reply&&r.reply.ja)RP.turns.push({role:"ai",ja:r.reply.ja,fu:r.reply.furi||"",en:r.reply.en||""});
    addXP(fb.score>=4?6:4);
    if(r&&r.done&&!RP.done){RP.done=true;addXP(10)}
  }catch(e){
    const c=e&&e.code;
    if(c==="not_granted"){RP.avail=false;RP.err=""}
    else if(c==="cancelled")RP.err="Stopped.";
    else if(c==="rate_limited")RP.err="Claude is busy for a moment. Wait a bit, then send again.";
    else RP.err="Claude couldn’t answer that one. Try sending again.";
  }
  RP.busy=false;RP.ctl=null;render();
  const m=document.getElementById("msgs");if(m)m.lastElementChild?.scrollIntoView({block:"nearest"});
}

/* ============ QUIZ ============ */
const QM=[
  {id:"smart",t:"Smart check",d:"Auto-picks what you learned: due, weak and mistaken items first"},
  {id:"kt",t:"Kanji test",d:"Meaning and reading of each kanji"},
  {id:"vt",t:"Word test",d:"Meaning, word and reading"},
  {id:"km",t:"Kanji → meaning",d:"See a kanji, pick its meaning"},
  {id:"kr",t:"Kanji → reading",d:"Pick the on and kun readings"},
  {id:"vm",t:"Word → meaning",d:"See a word, pick the English"},
  {id:"mv",t:"Meaning → word",d:"See English, pick the Japanese"},
  {id:"vr",t:"Word → reading",d:"Pick the correct hiragana"},
  {id:"gf",t:"Grammar fill-in",d:"Complete the sentence"},
  {id:"sf",t:"Sound families",d:"Kanji that share a sound piece"},
  {id:"mix",t:"Mixed",d:"A bit of everything"},
  {id:"rev",t:"My mistakes",d:"Questions you got wrong before"}
];
const Q={phase:"setup",mode:"smart",src:"any",kf:"N3",vf:"N3",gf:"All",n:20,list:[],i:0,picked:null,score:0,missed:[]};
const kpool=()=>{if(Q.src!=="any"){const L=learnedSet(Q.src);return K.filter(k=>L.has(k.id))}return Q.kf==="All"?K:K.filter(k=>k.tags.includes(Q.kf))};
const vpool=()=>{if(Q.src!=="any"){const L=learnedSet(Q.src);return V.filter(v=>L.has(v.id))}return Q.vf==="All"?V:V.filter(v=>v.tags.includes(Q.vf))};
const gpool=()=>Q.gf==="All"?G:G.filter(g=>g.cat===Q.gf);
function others(item,arr,key,grp){
  let pool=[...new Set(arr.filter(x=>x[grp]===item[grp]&&x[key]!==item[key]).map(x=>x[key]))];
  if(pool.length<3)pool=[...new Set(arr.filter(x=>x[key]!==item[key]).map(x=>x[key]))];
  return shuffle(pool).slice(0,3);
}
function makeQ(type,x){
  if(type==="km")return {x,type,ask:"What does this kanji mean?",prompt:`<div class="sq"><span lang="ja">${x.c}</span></div>`,ans:x.m,opts:shuffle([x.m,...others(x,K,"m","lvl")]),jp:false};
  if(type==="kr"){const r=readStr(x);const pool=K.filter(k=>k.lvl===x.lvl&&k.id!==x.id).map(readStr).filter(v=>v!==r);
    return {x,type,ask:"Which readings belong to this kanji?",prompt:`<div class="sq"><span lang="ja">${x.c}</span></div>`,ans:r,opts:shuffle([r,...shuffle([...new Set(pool)]).slice(0,3)]),jp:true}}
  if(type==="vm")return {x,type,ask:"What does this mean?",prompt:`<div class="q-word" lang="ja">${esc(x.w)}</div>`,ans:x.m,opts:shuffle([x.m,...others(x,V,"m","grp")]),jp:false};
  if(type==="mv")return {x,type,ask:"Which Japanese matches this meaning?",prompt:`<div class="q-en">${esc(x.m)}</div>`,ans:x.w,opts:shuffle([x.w,...others(x,V,"w","grp")]),jp:true};
  if(type==="vr")return {x,type,ask:"How is this read?",prompt:`<div class="q-word" lang="ja">${esc(x.w)}</div>`,ans:x.r,opts:shuffle([x.r,...others(x,V,"r","grp")]),jp:true};
  return {x,type,ask:"Choose what fits the blank.",prompt:`<p class="q-sent" lang="ja">${fr(x.s).replace("＿＿",'<span class="blank">？</span>')}</p>`,ans:x.a,opts:shuffle([x.a,...x.d]),jp:true};
}
function learnedPool(){return [...new Set([...Object.keys(store.srs),...Object.keys(store.learned),...Object.keys(store.k).filter(i=>store.k[i]==="known")])].filter(id=>BYID[id])}
function smartQs(N){
  const t=today(),pool=learnedPool();
  const scored=pool.map(id=>{const s=store.srs[id];let w=1+Math.random();
    if(s){if(s[0]<=t)w+=3+Math.min(3,(t-s[0])/3);w+=s[4]*1.5;if(s[1]<7)w+=1}
    w+=(store.w[id]||0)*3;return [id,w]}).sort((a,b)=>b[1]-a[1]).slice(0,N);
  return shuffle(scored.map(([id])=>{const x=BYID[id];
    if(id[0]==="k")return makeQ(Math.random()<.5?"km":"kr",x);
    if(id[0]==="g")return makeQ("gf",x);
    return makeQ(shuffle(["vm","mv","vr"].filter(t=>!(t==="vr"&&x.w===x.r)))[0],x)}));
}
function startQuiz(){
  let list=[];const N=Q.n;
  if(Q.mode==="today"&&Q.todayIds){startTodayTest(Q.todayIds);return}
  if(Q.mode==="smart"){const l=smartQs(Q.n);if(!l.length){Q.phase="setup";render();return}Object.assign(Q,{phase:"run",list:l,i:0,picked:null,score:0,missed:[]});render();return}
  if(Q.mode==="kt"||Q.mode==="vt"){
    const items=shuffle(Q.mode==="kt"?kpool():vpool()),types=Q.mode==="kt"?["km","kr"]:["vm","mv","vr"];
    const perm=new Map(items.map(x=>[x.id,shuffle(types).filter(t=>!(t==="vr"&&x.w===x.r))]));
    for(let r=0;r<types.length&&list.length<N;r++)for(const x of items){const t=perm.get(x.id)[r];if(t){list.push(makeQ(t,x));if(list.length>=N)break}}
    list=shuffle(list);
    Object.assign(Q,{phase:"run",list,i:0,picked:null,score:0,missed:[]});render();return;
  }
  if(Q.mode==="km"||Q.mode==="kr")list=shuffle(kpool()).slice(0,N).map(x=>makeQ(Q.mode,x));
  else if(["vm","mv","vr"].includes(Q.mode)){let p=vpool();if(Q.mode==="vr")p=p.filter(v=>v.w!==v.r);list=shuffle(p).slice(0,N).map(x=>makeQ(Q.mode,x))}
  else if(Q.mode==="gf")list=shuffle(gpool()).slice(0,N).map(x=>makeQ("gf",x));
  else if(Q.mode==="sf")list=shuffle(SFAM.filter(f=>(f.ka?1:0)+f.m.filter(m=>m.a&&!m.x).length>=2)).slice(0,N).map(f=>makeSF(f));
  else if(Q.mode==="mix"){const kp=kpool(),vp=vpool();for(let i=0;i<N;i++){const t=shuffle(["km","kr","vm","mv","gf"])[0];const src=t[0]==="k"?kp:t==="gf"?G:vp;list.push(makeQ(t,src[Math.floor(Math.random()*src.length)]))}}
  else list=shuffle(Object.keys(store.w).filter(id=>BYID[id])).slice(0,N).map(id=>{const x=BYID[id];const t=id[0]==="k"?(Math.random()<.5?"km":"kr"):id[0]==="v"?"vm":"gf";return makeQ(t,x)});
  Object.assign(Q,{phase:"run",list,i:0,picked:null,score:0,missed:[]});
  render();
}
function explain(q){
  const x=q.x;
  if(q.type==="sf"){const f=q.sf;return `<p>The piece <b lang="ja">${f.k}</b> hints at the sound <b lang="ja">${esc(f.r)}</b>.</p><div class="sf-row">${(f.ka?sfChip(f.k,f.ko,"",""):"")+f.m.filter(m=>!m.x).map(m=>sfChip(m.c,m.o,m.a?"":"dim","")).join("")}</div>${f.m.some(m=>m.x)?`<p class="sf-ex">Exceptions: ${f.m.filter(m=>m.x).map(m=>`<span lang="ja">${m.c} ${esc(m.o)}</span>`).join(" · ")}</p>`:""}`}
  if(q.type==="km"||q.type==="kr")return `<p class="jp" lang="ja">${x.c}　${esc(x.m)}</p><p lang="ja">${readStr(x)}</p>${hook(x)}`;
  if(q.type==="gf")return `<p><b lang="ja">${esc(x.p)}</b>: ${esc(x.m)}</p><p class="jp" lang="ja">${filled(x)}</p><p class="tr">${esc(x.t)}</p>`;
  return `<p class="jp" lang="ja">${esc(x.w)}（${esc(x.r)}）</p><p>${esc(x.m)}</p>`;
}
function chipRow(label,key,list){return `<div class="field"><span>${label}</span><div class="chips">${list.map(c=>`<button class="chip" data-qf="${key}" data-val="${esc(c)}" aria-pressed="${Q[key]===c}">${esc(CHIPLABEL[c]||c)}</button>`).join("")}</div></div>`}
function quizView(){
  if(Q.phase==="setup"){
    const mist=Object.keys(store.w).length;
    const modes=QM.map(m=>`<button class="mode" data-qmode="${m.id}" aria-pressed="${Q.mode===m.id}" ${(m.id==="rev"&&!mist)||(m.id==="smart"&&!learnedPool().length)?"disabled":""}><b>${m.t}</b><span>${m.id==="rev"?(mist?`${mist} saved`:"None yet — take a quiz first"):m.id==="smart"&&!learnedPool().length?"Learn a few cards first":m.d}</span></button>`).join("");
    const isK=["km","kr","kt"].includes(Q.mode),isV=["vm","mv","vr","vt"].includes(Q.mode),srcOn=isK||isV||Q.mode==="mix";
    const km=(isK||Q.mode==="mix")&&Q.src==="any",vm=(isV||Q.mode==="mix")&&Q.src==="any",gm=Q.mode==="gf";
    const cnt=src=>(isK?countLearned(src,"k"):0)+(isV?countLearned(src,"v"):0)+(Q.mode==="mix"?countLearned(src,"k")+countLearned(src,"v"):0);
    const SRC=[["today","Learned today"],["week","Last 7 days"],["all","Everything I’ve learned"],["any","Everything"]];
    const srcRow=srcOn?`<div class="field"><span>What to test</span><div class="chips">${SRC.map(([v,l])=>{const n=v==="any"?null:cnt(v);return `<button class="chip" data-qf="src" data-val="${v}" aria-pressed="${Q.src===v}" ${n===0?"disabled":""}>${l}${n!==null?` <small>${n}</small>`:""}</button>`}).join("")}</div></div>`:"";
    const empty=srcOn&&Q.src!=="any"&&cnt(Q.src)===0;
    return `<h1>Quiz</h1><p class="lede" style="margin-bottom:20px">+3 XP per correct answer. Wrong answers go to “My mistakes”.</p>
    <div class="field"><span>Question type</span><div class="modes">${modes}</div></div>
    ${srcRow}
    ${km?chipRow("Kanji set","kf",["All","N3","N4","N5","Bonus"]):""}
    ${vm?chipRow("Word set","vf",SECS.vocab.chips):""}
    ${gm?chipRow("Grammar group","gf",SECS.grammar.chips):""}
    ${chipRow("Number of questions","n",[10,20,30])}
    ${empty?`<p class="count">Nothing learned in this range yet — do today’s review first, or choose “Everything”.</p>`:""}
    <button class="btn primary qstart" data-act="startquiz" ${empty?"disabled":""}>Start: ${esc((QM.find(m=>m.id===Q.mode)||{t:"quiz"}).t)} →</button>`;
  }
  if(Q.phase==="done"){
    const n=Q.list.length,pct=Math.round(Q.score/n*100);
    const msg=pct===100?"Perfect score.":pct>=70?"Strong work. Review the misses below.":"Keep going — the misses below are now in “My mistakes”.";
    return `<div class="qwrap"><div class="done"><div class="big" lang="ja">${pct>=70?"合格":"復習"}</div><h2>${Q.score} / ${n} correct</h2><p class="lede" style="margin:0 auto">${msg}</p>
      ${Q.missed.length?`<ul class="missed">${Q.missed.map(q=>`<li><span lang="ja">${q.type==="gf"?esc(plainFilled(q.x)):esc(q.x.c||q.x.w)}</span> — ${esc(q.ans)}</li>`).join("")}</ul>`:""}
      ${Q.mode==="today"&&Q.missed.length?`<p class="count" style="margin-top:12px">The ones you missed will come back in your review later today.</p>`:""}<div class="acts">${Q.mode==="today"?`<a class="btn primary" href="#dojo" style="text-decoration:none">Back to Today</a><button class="btn" data-act="startquiz">Take it again</button>`:`<button class="btn primary" data-act="startquiz">Same quiz again</button><button class="btn" data-act="quizsetup">Choose another quiz</button>`}</div></div></div>`;
  }
  const q=Q.list[Q.i];if(!q){Q.phase="setup";return quizView()}
  const ans=Q.picked!==null;
  const opts=q.opts.map((o,i)=>{let cls="opt"+(q.jp?" jpopt":"");if(ans){if(o===q.ans)cls+=" right";else if(i===Q.picked)cls+=" wrong"}
    return `<button class="${cls}" data-pick="${i}" ${ans?"disabled":""}><span class="n">${i+1}</span><span ${q.jp?'lang="ja"':""}>${q.type==="ko"?esc(o):fr(o)}</span></button>`}).join("");
  const ok=ans&&q.opts[Q.picked]===q.ans;
  const tc=Q.mode==="today"?{v:Q.list.filter(q=>q.x.id[0]==="v").length,k:Q.list.filter(q=>q.x.id[0]==="k").length,g:Q.list.filter(q=>q.x.id[0]==="g").length}:null;
  return `<div class="qwrap">${tc?`<div class="todayhead"><div><b>Today’s test</b><span class="count"> · on what you just learned: ${[tc.v&&tc.v+" word"+(tc.v>1?"s":""),tc.k&&tc.k+" kanji",tc.g&&tc.g+" grammar"].filter(Boolean).join(", ")}</span></div><button class="linkbtn" data-act="skiptest">Skip test</button></div>`:""}<p class="count" style="margin:0 0 8px"><button class="linkbtn" data-act="quizsetup">← Quiz menu</button></p><div class="qmeta"><span>Question ${Q.i+1} of ${Q.list.length}</span><span>${Q.score} correct</span></div>
    <div class="qbar"><i style="width:${(Q.i/Q.list.length)*100}%"></i></div>
    <div class="qcard"><p class="qask">${q.ask}</p>${q.prompt}</div>${q.jp&&q.type!=="sf"?`<p class="count" style="text-align:right;margin:-6px 0 8px">${FB()}</p>`:""}
    <div class="opts">${opts}</div>
    ${ans?`<div class="fb ${ok?"ok":"no"}" role="status"><h3>${ok?"Correct":"Not quite — the answer is “"+esc(q.ans)+"”"}</h3>${explain(q)}</div>
    `:""}
    <div class="acts qnav"><button class="btn" data-act="qprev" ${Q.i?"":"disabled"}>← Previous</button>${ans?`<button class="btn primary next" data-act="nextq">${Q.i+1<Q.list.length?"Next question →":"See results"}</button>`:""}</div>
  </div>`;
}
function pick(i){
  if(Q.picked!==null)return;
  const q=Q.list[Q.i];Q.picked=i;q.pk=i;const id=q.x.id;
  const ok=q.opts[i]===q.ans;
  if(ok){Q.score++;if(q.type!=="sf"&&store.w[id]){store.w[id]--;if(store.w[id]<=0)delete store.w[id]}}
  else{if(q.type!=="sf")store.w[id]=(store.w[id]||0)+1;Q.missed.push(q);if(Q.mode==="today"&&store.srs[id]){store.srs[id][0]=today();store.srs[id][1]=0}}
  if(Q.mode==="today"&&Q.auto){if(!ok){store.k[id]="again";if(!store.srs[id])store.srs[id]=[today(),0,250,0,1]}else if(!store.srs[id])store.srs[id]=srsCalc(id,2)}
  if(Q.mode==="smart"){const s=store.srs[id];if(!ok)store.srs[id]=s?srsCalc(id,0):[today(),0,250,0,1];else if(s&&s[0]<=today())store.srs[id]=srsCalc(id,2);markLearned(id)}
  if(ok)addXP(3);else save();
  render();
  const b=main.querySelector('[data-act="nextq"]');if(b)b.focus();
  if(q.type!=="sf")speak(q.type==="gf"?plainFilled(q.x):q.x.c?(q.x.ex[0]?q.x.ex[0][0]:q.x.c):q.x.w);
}

/* ============ MATCH ============ */
const MSETS={kN3:["N3 kanji",()=>K.filter(k=>k.lvl==="N3"),"c"],kN4:["N4 & N5 kanji",()=>K.filter(k=>k.lvl==="N4"||k.lvl==="N5"),"c"],
  vN3:["N3 words",()=>V.filter(v=>v.lvl==="N3"),"w"],Workplace:["Workplace words",()=>V.filter(v=>v.cat==="Workplace"),"w"],
  Keigo:["Keigo",()=>V.filter(v=>v.cat==="Keigo"),"w"],"Business phrases":["Business phrases",()=>V.filter(v=>v.cat==="Business phrases"),"w"]};
const M={set:"kN3",tiles:[],sel:null,start:0,pen:0,done:false,bad:[],final:0};
let timerId=null;
function stopTimer(){if(timerId){clearInterval(timerId);timerId=null}}
function newMatch(){
  stopTimer();
  const [,fn,key]=MSETS[M.set];
  const items=[];const seenM=new Set();
  for(const x of shuffle(fn())){const mm=x.m.split(",")[0];if(seenM.has(mm))continue;seenM.add(mm);items.push(x);if(items.length===6)break}
  M.tiles=shuffle(items.flatMap(x=>[{pid:x.id,label:x[key],jp:true,gone:false},{pid:x.id,label:x.m.split(",").slice(0,2).join(","),jp:false,gone:false}]));
  Object.assign(M,{sel:null,start:0,pen:0,done:false,bad:[],final:0});
}
const elapsed=()=>M.start?((Date.now()-M.start)/1000+M.pen):0;
function matchView(){
  if(!M.tiles.length)newMatch();
  const best=store.best[M.set];
  const sets=Object.entries(MSETS).map(([k,v])=>`<button class="chip" data-mset="${esc(k)}" aria-pressed="${M.set===k}">${v[0]}</button>`).join("");
  const grid=M.done?`<div class="done"><div class="big" lang="ja">速</div><h2>${M.final.toFixed(1)} seconds</h2><p class="lede" style="margin:0 auto">${best&&M.final<=best?"New best time!":best?`Your best is ${best.toFixed(1)} s.`:""}</p><div class="acts"><button class="btn primary" data-act="newmatch">Play again</button></div></div>`
  :`<div class="mgrid">${M.tiles.map((t,i)=>`<button class="mt ${t.jp?"jp":""} ${M.sel===i?"sel":""} ${M.bad.includes(i)?"bad":""} ${t.gone?"gone":""}" data-tile="${i}" ${t.jp?'lang="ja"':""} ${t.gone?'tabindex="-1" aria-hidden="true"':""}>${esc(t.label)}</button>`).join("")}</div>`;
  return `${PB()}<h1>Match</h1><p class="lede" style="margin-bottom:16px">Tap a Japanese tile, then its meaning. Each wrong pair adds one second. +10 XP per finished board.</p>
  <div class="chips">${sets}</div>
  <div class="mbar"><span class="timer" id="timer">${M.done?M.final.toFixed(1):elapsed().toFixed(1)} s</span><span class="count">${best?`Best: ${best.toFixed(1)} s`:"No best time yet"}</span><button class="btn" data-act="newmatch">New board</button></div>
  ${grid}`;
}
function tapTile(i){
  const t=M.tiles[i];if(t.gone||M.done)return;
  if(!M.start){M.start=Date.now();timerId=setInterval(()=>{const el=document.getElementById("timer");if(el)el.textContent=elapsed().toFixed(1)+" s"},100)}
  if(M.sel===null){M.sel=i;M.bad=[];render();return}
  if(M.sel===i){M.sel=null;render();return}
  const a=M.tiles[M.sel];
  if(a.pid===t.pid&&a.jp!==t.jp){
    a.gone=t.gone=true;M.sel=null;speak(t.jp?t.label:a.label);
    if(M.tiles.every(x=>x.gone)){M.final=elapsed();stopTimer();M.done=true;if(!store.best[M.set]||M.final<store.best[M.set])store.best[M.set]=M.final;addXP(10)}
  }else{M.pen+=1;M.bad=[M.sel,i];M.sel=null;setTimeout(()=>{M.bad=[];if(view==="match")render()},450)}
  render();
}

/* ============ STORY PATH ============ */
const PNORM={"⻖":"阝","⻏":"阝","竹":"⺮","𥫗":"⺮","辶":"⻌","釒":"金","⺼":"月"};
const pn=c=>PNORM[c]||c;
const BLOCKS=[["亻","person","🧍"],["口","mouth","👄"],["言","words","💬"],["氵","water","💧"],["扌","hand","✋"],["木","tree","🌳"],["日","sun","☀️"],["月","moon / body","🌙"],["心","heart","❤️"],["忄","heart (side form)","💗"],["糸","thread","🧵"],["貝","money","💰"],["土","earth","🟫"],["女","woman","👩"],["子","child","👶"],["宀","roof","🏠"],["艹","grass","🌿"],["⻌","road","🛣️"],["阝","hill","⛰️"],["刂","knife","🔪"],["力","power","💪"],["田","field","🌾"],["目","eye","👁️"],["金","metal","🔩"],["火","fire","🔥"],["⺮","bamboo","🎋"],["攵","strike","👊"],["疒","sickness","🤒"],["广","shelter","⛺"],["彳","going","🚶"],["礻","altar","🕯️"],["衤","clothes","👘"]];
const BEMO={};BLOCKS.forEach(b=>BEMO[b[0]]=b[2]);
const BSET=new Set(BLOCKS.map(b=>b[0]));
const partEmoji=(ch,name)=>BEMO[pn(ch)]||EMO[name]||"";
const cap=s=>s.charAt(0).toUpperCase()+s.slice(1);
const MEMO={"民":"👥","米":"🍚","面":"🎭","示":"👉","失":"💨","非":"🚫","危":"⚠️","王":"👑","互":"🤝","耳":"👂","手":"✋","力":"💪","目":"👁️","田":"🌾","用":"🛠️","心":"❤️","工":"🔨","夕":"🌆","牛":"🐄","日":"☀️","一":"1️⃣","人":"🧍","大":"🐘","十":"🔟","二":"2️⃣","長":"📏","月":"🌙","生":"🌱","金":"🪙","入":"➡️","子":"👶","八":"8️⃣","小":"🐜","山":"⛰️","女":"👩","川":"🏞️","水":"💧","西":"🧭","土":"🟫","木":"🌳","食":"🍚","車":"🚗","火":"🔥","父":"👨","雨":"🌧️"};
function kparts(k){return k.comp.length?k.comp:k.parts.slice(0,3)}
function tileEmo(k){return kparts(k).map(p=>partEmoji(p[0],p[1])).filter(Boolean).slice(0,4).join("")||MEMO[k.c]||""}
function formula(k){
  const mean=k.m.split(",")[0].trim();
  const P=kparts(k);
  if(!P.length||!P.some(p=>partEmoji(p[0],p[1]))&&MEMO[k.c])return{emo:MEMO[k.c]||"",line:`<b>${esc(cap(mean))}</b>`};
  const emo=P.map(p=>partEmoji(p[0],p[1])||`<span lang="ja">${esc(p[0])}</span>`).join(" + ");
  const line=cap(P.map(p=>esc(p[1]||p[0])).join(" + "))+` = <b>${esc(mean)}</b>`;
  return{emo,line};
}
const PTRIV=new Set(["一","丿","丨","丶","·","?","亅","二","十","口","人","大","日","儿","八"]);
let PATH=null;
function buildPath(){
  const ks=K.filter(k=>k.lvl==="N3");
  const cnt={};
  ks.forEach(k=>new Set(k.comp.map(p=>pn(p[0]))).forEach(c=>{if(!PTRIV.has(c))cnt[c]=(cnt[c]||0)+1}));
  const fam={},misc=[];
  ks.forEach(k=>{
    let best=null,bestScore=0;
    for(const p of k.comp){const c=pn(p[0]);if(PTRIV.has(c)||(cnt[c]||0)<3)continue;
      const sc=cnt[c]+(BSET.has(c)?0:100); // prefer shared non-radical parts (they often share a reading)
      if(sc>bestScore){bestScore=sc;best=[c,p[1]]}}
    if(best)(fam[best[0]]=fam[best[0]]||{c:best[0],name:best[1],ks:[]}).ks.push(k);else misc.push(k);
  });
  let fams=Object.values(fam);
  fams.forEach(f=>{if(f.ks.length<3){misc.push(...f.ks);f.ks=[]}});
  fams=fams.filter(f=>f.ks.length).sort((a,b)=>(BSET.has(b.c)-BSET.has(a.c))||b.ks.length-a.ks.length);
  const L=[];
  for(const f of fams){const n=Math.ceil(f.ks.length/6),size=Math.ceil(f.ks.length/n);
    for(let i=0;i<n;i++){const part=f.ks.slice(i*size,(i+1)*size);if(part.length)L.push({key:f.c,name:f.name,ks:part})}}
  misc.sort((a,b)=>K.indexOf(a)-K.indexOf(b));
  for(let i=0;i<misc.length;i+=5)L.push({key:"",name:"",ks:misc.slice(i,i+5)});
  L.forEach((l,i)=>{l.id=i;
    const c={};l.ks.forEach(k=>(k.on||"").split("、").filter(Boolean).forEach(r=>c[r]=(c[r]||0)+1));
    const top=Object.entries(c).sort((a,b)=>b[1]-a[1])[0];l.reading=top&&(top[1]>=3||(top[1]>=2&&l.ks.length<=3))?top[0]:"";l.rcount=top?top[1]:0;
  });
  return L;
}
const famLabel=l=>l.key?`<span lang="ja">${esc(l.key)}</span> ${partEmoji(l.key,l.name)} ${esc(l.name)} family`:"Mixed kanji";
function pathView(){
  const P=PATH||(PATH=buildPath());
  const done=P.filter(l=>store.path[l.id]);const kn=done.reduce((a,l)=>a+l.ks.length,0);const total=P.reduce((a,l)=>a+l.ks.length,0);
  const next=P.find(l=>!store.path[l.id]);
  const pk=Object.values(store.parts).filter(Boolean).length;
  return `<div class="sec-head"><div><h1>Story path</h1><p class="lede">Every N3 kanji in small families: one picture, one line, two key words — then a quick check.</p></div></div>
  ${!store.partsDone?`<div class="panel step1"><div><b>First: check your building blocks</b><p class="count" style="margin:4px 0 0">32 common parts like 亻 person and 氵 water. About 3 minutes — then every story makes sense.</p></div><div class="acts-l" style="margin:0"><a class="btn primary" href="#parts" style="text-decoration:none">Start parts check</a><button class="btn" data-act="skipparts">Skip</button></div></div>`
  :`<p class="count" style="margin:0 0 14px">Building blocks: ${pk} / ${BLOCKS.length} known · <a href="#parts">Practice parts</a></p>`}
  ${next?`<div class="panel nextl">
    <div class="count">Next · Lesson ${next.id+1} of ${P.length}</div>
    <h2 class="nl-title">${famLabel(next)}</h2>
    <div class="nl-ks" lang="ja">${next.ks.map(k=>`<span>${k.c}</span>`).join("")}</div>
    ${next.reading&&next.rcount>=2?`<p class="count" style="margin:0 0 12px">Reading shortcut: ${next.rcount} of these read <b lang="ja">${next.reading}</b></p>`:""}
    <button class="btn primary big-btn" data-lesson="${next.id}">Start lesson (${next.ks.length} kanji · about 5 min)</button>
  </div>`:`<div class="panel nextl"><h2 class="nl-title">You’ve finished every lesson 🎉</h2><p class="count">Your daily review keeps them fresh. Replay any lesson below.</p></div>`}
  <div class="goal" style="margin:18px 0"><div class="goal-bar"><i style="width:${Math.round(kn/total*100)}%"></i></div><span>${kn} / ${total} N3 kanji · ${done.length} / ${P.length} lessons</span></div>
  <div class="lgrid">${P.map(l=>{const r=store.path[l.id];return `<button class="lcard ${r?"done":""} ${l===next?"isnext":""}" data-lesson="${l.id}"><span class="count">Lesson ${l.id+1}${r?` · ✓ ${r.s}/${r.n}`:""}</span><span class="lks" lang="ja">${l.ks.map(k=>k.c).join("")}</span><span class="count">${l.key?`<span lang="ja">${esc(l.key)}</span> ${esc(l.name)}`:"Mixed"}</span></button>`}).join("")}</div>`;
}
/* ---- lesson ---- */
const LS={id:null,step:"learn",i:0,more:false,qs:[],qi:0,picked:null,score:0,wrong:new Set()};
function startLesson(id){Object.assign(LS,{id:+id,step:"learn",i:0,more:false,qs:[],qi:0,picked:null,score:0,wrong:new Set()});if(location.hash!=="#lesson")location.hash="#lesson";else render()}
function storyCard(k){
  const f=formula(k),kw=k.ex.slice(0,2);
  return `<div class="scard2">
    <div class="sc-k" lang="ja">${k.c}</div>
    <div class="sc-m">${esc(k.m.split(",").slice(0,2).join(","))}</div>
    ${f.emo?`<div class="sc-emo" aria-hidden="true">${f.emo}</div>`:""}
    <p class="sc-line">${f.line}</p>
    ${kw.length?`<div class="sc-words">${kw.map(([w,r,m])=>`<button class="kw" data-speak="${esc(w)}" aria-label="Listen: ${esc(w)}"><b lang="ja">${esc(w)}</b><span lang="ja">${esc(r)}</span><small>${esc(m)}</small></button>`).join("")}</div>`:""}
    <button class="linkbtn sc-morebtn" data-lmore="1">${LS.more?"Hide details":"More: colored picture, full story, readings"}</button>
    ${LS.more?`<div class="sc-more">${kanjiDetail(k)}</div>`:""}
  </div>`;
}
function lessonQs(l){
  const qs=[];
  l.ks.forEach(k=>{
    const share=K.filter(x=>x!==k&&x.comp.some(p=>k.comp.some(q=>pn(q[0])===pn(p[0])&&!PTRIV.has(pn(p[0])))));
    const opts=[k.c];
    for(const x of [...shuffle(l.ks.filter(x=>x!==k)),...shuffle(share)]){if(opts.length>=4)break;if(!opts.includes(x.c))opts.push(x.c)}
    while(opts.length<4){const r=K[Math.floor(Math.random()*K.length)].c;if(!opts.includes(r))opts.push(r)}
    const f=formula(k);
    qs.push({t:"k",k,ask:"Which kanji matches this story?",prompt:`${f.emo?`<div class="sc-emo">${f.emo}</div>`:""}<p class="sc-line">${f.line}</p>`,ans:k.c,opts:shuffle(opts)});
    if(k.ex[0]){
      const [w,r]=k.ex[0];const o=[r];
      const near=V.filter(v=>v.w!==w&&v.r!==r&&v.w.includes(k.c)).map(v=>v.r);
      const rnd=V.filter(v=>v.r!==r&&/[\u4e00-\u9fff]/.test(v.w)&&Math.abs(v.r.length-r.length)<=1).map(v=>v.r);
      for(const x of [...shuffle(near),...shuffle(rnd)]){if(o.length>=4)break;if(!o.includes(x))o.push(x)}
      qs.push({t:"r",k,w,ask:"How do you read this word?",prompt:`<div class="q-word" lang="ja">${esc(w)}</div>`,ans:r,opts:shuffle(o)});
    }
  });
  return shuffle(qs);
}
function lessonView(){
  const P=PATH||(PATH=buildPath());const l=P[LS.id];
  if(!l)return pathView();
  const head=`<div class="lhead"><a class="btn" href="#path" style="text-decoration:none">← Path</a><div><b>Lesson ${l.id+1}</b> · ${famLabel(l)}</div></div>`;
  if(LS.step==="learn"){
    const k=l.ks[LS.i],last=LS.i===l.ks.length-1;
    return `${head}<div class="ldots" aria-label="Card ${LS.i+1} of ${l.ks.length}">${l.ks.map((x,i)=>`<i class="${i===LS.i?"on":i<LS.i?"seen":""}"></i>`).join("")}</div>
    ${LS.i===0&&l.reading&&l.rcount>=2?`<p class="tipbar">💡 Family shortcut: ${l.rcount} kanji in this lesson read <b lang="ja">${l.reading}</b>.</p>`:""}
    ${storyCard(k)}
    <div class="lnav"><button class="btn" data-lnav="-1" ${LS.i===0?"disabled":""}>← Back</button>${last?`<button class="btn primary" data-act="lcheck">Start the check</button>`:`<button class="btn primary" data-lnav="1">Next kanji →</button>`}</div>`;
  }
  if(LS.step==="check"){
    const q=LS.qs[LS.qi],ans=LS.picked!==null,ok=ans&&q.opts[LS.picked]===q.ans;
    return `${head}<div class="qwrap"><div class="qmeta"><span>Check ${LS.qi+1} of ${LS.qs.length}</span><span>${LS.score} correct</span></div>
    <div class="qbar"><i style="width:${LS.qi/LS.qs.length*100}%"></i></div>
    <div class="qcard"><p class="qask">${q.ask}</p>${q.prompt}</div>
    <div class="opts ${q.t==="k"?"kopts":""}">${q.opts.map((o,i)=>{let c="opt jpopt";if(ans){if(o===q.ans)c+=" right";else if(i===LS.picked)c+=" wrong"}return `<button class="${c}" data-lpick="${i}" ${ans?"disabled":""}><span class="n">${i+1}</span><span lang="ja">${esc(o)}</span></button>`}).join("")}</div>
    ${ans?`<div class="fb ${ok?"ok":"no"}" role="status"><h3>${ok?"Correct":"Not quite — it’s “"+esc(q.ans)+"”"}</h3><p><b lang="ja">${q.k.c}</b> ${esc(q.k.m.split(",")[0])}${q.t==="r"?` · <span lang="ja">${esc(q.w)}（${esc(q.ans)}）</span>`:""}</p></div>
    <button class="btn primary next" data-act="lnextq">${LS.qi+1<LS.qs.length?"Next":"See results"}</button>`:""}</div>`;
  }
  const n=LS.qs.length,nx=P.find(x=>!store.path[x.id]);
  return `${head}<div class="done"><div class="big" lang="ja">${LS.score>=n*.7?"合格":"復習"}</div><h2>${LS.score} / ${n} correct</h2>
    <p class="lede" style="margin:0 auto">${l.ks.length} kanji added to your daily review${LS.wrong.size?` — the ${LS.wrong.size} you missed come back today`:""}.</p>
    <div class="sc-mini" lang="ja">${l.ks.map(k=>`<span class="${LS.wrong.has(k.id)?"miss":""}">${k.c}</span>`).join("")}</div>
    <div class="acts">${nx?`<button class="btn primary" data-lesson="${nx.id}">Next lesson: ${nx.ks.map(k=>k.c).join("")}</button>`:""}<a class="btn" href="#path" style="text-decoration:none">Back to path</a></div></div>`;
}
function lessonPick(i){
  if(LS.picked!==null)return;
  const q=LS.qs[LS.qi];LS.picked=i;
  if(q.opts[i]===q.ans){LS.score++;addXP(2);speak(q.t==="r"?q.w:(q.k.ex[0]?q.k.ex[0][0]:q.k.c))}else{LS.wrong.add(q.k.id);save()}
  render();main.querySelector('[data-act="lnextq"]')?.focus();
}
function finishLesson(){
  const l=PATH[LS.id];
  const prev=store.path[l.id];
  store.path[l.id]={s:LS.score,n:LS.qs.length,d:today()};
  l.ks.forEach(k=>{const miss=LS.wrong.has(k.id);
    if(!store.srs[k.id])store.srs[k.id]=miss?[today(),0,250,0,0]:[today()+1,1,250,1,0];
    else if(miss)store.srs[k.id][0]=today();});
  LS.step="done";
  if(!prev)addXP(10);else save();
  render();
}
/* ---- parts check & lessons ---- */
const PT={phase:"all",qs:[],qi:0,picked:null,score:0,learn:[],li:0};
function blockPic(k,ch,size){
  const strokes=SD[k.c]||[];const on=new Set();k.comp.forEach(p=>{if(pn(p[0])===ch)p[2].forEach(n=>on.add(n))});
  return `<svg class="kpic" viewBox="0 0 109 109" width="${size}" height="${size}" aria-hidden="true">${strokes.map((d,i)=>`<path d="${d}" class="${on.has(i)?"pc1":"pcx dim"}"/>`).join("")}</svg>`;
}
function rubyWord(w,r){
  w=w.replace(/\s*[(（].*?[)）]/g,"");r=r.replace(/\s*[(（].*?[)）]/g,"");
  const KJ=/[\u3400-\u9fff\u3005]/;
  const runs=w.match(/[\u3400-\u9fff\u3005]+|[^\u3400-\u9fff\u3005]+/g)||[w];
  const toH=t=>t.replace(/[\u30a1-\u30f6]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));
  const pat=new RegExp("^"+runs.map(x=>KJ.test(x)?"(.+?)":"("+toH(x).replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+")").join("")+"$");
  const m=toH(r).match(pat);
  if(!m)return `<ruby>${esc(w)}<rt>${esc(r)}</rt></ruby>`;
  return runs.map((x,i)=>KJ.test(x)?`<ruby>${esc(x)}<rt>${esc(m[i+1])}</rt></ruby>`:esc(x)).join("");
}
function blockExamples(ch){
  const rank={N5:0,N4:1,N3:2,Bonus:3};
  return K.filter(k=>k.comp.some(p=>pn(p[0])===ch)).sort((a,b)=>(!!b.ex.length-!!a.ex.length)||rank[a.lvl]-rank[b.lvl]).slice(0,3);
}
function startParts(){
  PT.qs=shuffle(BLOCKS).map(b=>{const others=shuffle(BLOCKS.filter(x=>x[1]!==b[1]&&x[2]!==b[2])).slice(0,3);return{b,opts:shuffle([b,...others])}});
  Object.assign(PT,{phase:"quiz",qi:0,picked:null,score:0});render();
}
function partsView(){
  const head=`<div class="lhead"><a class="btn" href="#kanji" style="text-decoration:none">← Kanji</a><div><b>Parts guide</b> · ${BLOCKS.length} common building blocks</div></div>`;
  if(PT.phase==="intro")return `${head}<div class="panel" style="max-width:620px">
    <h2 style="margin-top:0">Quick parts check</h2>
    <p class="lede">Most kanji are built from a small set of parts. Each part has one emoji that stays the same in every story — 亻 is always 🧍 person, 氵 is always 💧 water. Let’s see which ones you already know.</p>
    <div class="blk-preview" lang="ja">${BLOCKS.slice(0,12).map(b=>`<span>${b[0]}</span>`).join("")}<span class="count">…</span></div>
    <div class="acts-l"><button class="btn primary" data-act="ptstart">Start (${BLOCKS.length} questions · about 3 min)</button><button class="btn" data-act="ptall">Just show me all parts</button></div></div>`;
  if(PT.phase==="quiz"){
    const q=PT.qs[PT.qi],ans=PT.picked!==null,ok=ans&&q.opts[PT.picked]===q.b;
    return `${head}<div class="qwrap"><div class="qmeta"><span>Part ${PT.qi+1} of ${PT.qs.length}</span><span>${PT.score} known</span></div>
    <div class="qbar"><i style="width:${PT.qi/PT.qs.length*100}%"></i></div>
    <div class="qcard"><p class="qask">What does this part mean?</p><div class="blk-big" lang="ja">${q.b[0]}</div></div>
    <div class="opts">${q.opts.map((o,i)=>{let c="opt";if(ans){if(o===q.b)c+=" right";else if(i===PT.picked)c+=" wrong"}return `<button class="${c}" data-ptpick="${i}" ${ans?"disabled":""}><span class="n">${i+1}</span><span>${ans?o[2]+" ":""}${esc(o[1])}</span></button>`}).join("")}<button class="opt idk" data-ptpick="-1" ${ans?"disabled":""}><span class="n">?</span><span>I don’t know</span></button></div>
    ${ans?`<div class="fb ${ok?"ok":"no"}" role="status"><h3>${ok?"You know it":"New part"}: <span lang="ja">${q.b[0]}</span> = ${q.b[2]} ${esc(q.b[1])}</h3><p class="count">Seen in <span lang="ja">${blockExamples(q.b[0]).map(k=>k.c).join("、")}</span></p></div>
    <button class="btn primary next" data-act="ptnext">${PT.qi+1<PT.qs.length?"Next":"See results"}</button>`:""}</div>`;
  }
  if(PT.phase==="result"){
    const miss=BLOCKS.filter(b=>!store.parts[b[0]]);
    return `${head}<div class="done"><div class="big" lang="ja">${miss.length<=4?"良":"学"}</div><h2>You know ${BLOCKS.length-miss.length} of ${BLOCKS.length} parts</h2>
      <p class="lede" style="margin:0 auto">${miss.length?`Learn the ${miss.length} new part${miss.length===1?"":"s"} now — it only takes a few minutes.`:"You know them all."}</p>
      ${miss.length?`<div class="blk-preview" lang="ja" style="justify-content:center">${miss.map(b=>`<span>${b[0]}</span>`).join("")}</div>`:""}
      <div class="acts">${miss.length?`<button class="btn primary" data-act="ptlearn">Learn ${miss.length} new part${miss.length===1?"":"s"}</button>`:""}<button class="btn ${miss.length?"":"primary"}" data-act="ptall">See all parts</button></div></div>`;
  }
  if(PT.phase==="learn"){
    const b=PT.learn[PT.li],ex=blockExamples(b[0]),last=PT.li===PT.learn.length-1;
    return `${head}<div class="ldots">${PT.learn.map((x,i)=>`<i class="${i===PT.li?"on":i<PT.li?"seen":""}"></i>`).join("")}</div>
    <div class="scard2"><div class="sc-k" lang="ja">${b[0]}</div><div class="sc-emo">${b[2]}</div><div class="sc-m">${esc(b[1])}</div>
    <p class="sc-line">Whenever you see <b lang="ja">${b[0]}</b> inside a kanji, picture ${b[2]} <b>${esc(b[1])}</b>.</p>
    <div class="blk-ex">${(()=>{const used=new Set();return ex.map(k=>{const wd=k.ex.find(e=>!used.has(e[0]))||k.ex[0];if(wd)used.add(wd[0]);return `<div>${blockPic(k,b[0],84)}<div><b lang="ja">${k.c}</b> <span class="count">${esc(k.m.split(",")[0])}</span></div>${wd?`<button class="bw" data-speak="${esc(wd[0])}" aria-label="Listen: ${esc(wd[0])}"><span class="bw-j" lang="ja">${rubyWord(wd[0],wd[1])}</span><small>${esc(wd[2])}</small></button>`:""}</div>`}).join("")})()}</div></div>
    <div class="lnav"><button class="btn" data-ptnav="-1" ${PT.li===0?"disabled":""}>← Back</button>${last?`<button class="btn primary" data-act="ptdone">${PT.learn.length===1?"Back to all parts":"Done"}</button>`:`<button class="btn primary" data-ptnav="1">Next part →</button>`}</div>`;
  }
  // all parts reference
  return `${head}<p class="lede" style="margin-bottom:16px">Most kanji are built from these parts. Each one has an emoji that stays the same in every story. Tap a part to see it inside real kanji.</p>
  <div class="blk-grid">${BLOCKS.map(b=>`<button class="blk ${store.parts[b[0]]?"":"unk"}" data-ptone="${b[0]}"><span class="blk-c" lang="ja">${b[0]}</span><span>${b[2]} ${esc(b[1])}</span><span class="count" lang="ja">${blockExamples(b[0]).map(k=>k.c).join(" ")}</span></button>`).join("")}</div>
  <div class="acts-l"><button class="btn" data-act="ptstart">Test yourself (optional)</button></div>`;
}
function partsPick(i){
  if(PT.picked!==null)return;const q=PT.qs[PT.qi];PT.picked=i<0?-1:i;
  const ok=i>=0&&q.opts[i]===q.b;store.parts[q.b[0]]=ok?1:0;if(ok){PT.score++;addXP(1)}else save();render();
  main.querySelector('[data-act="ptnext"]')?.focus();
}

