function rdPick(i){const o=EX.rd,qd=RD[o.order[o.i]].qs[o.qi];if(o.picked!==null)return;o.picked=i;(o.hist||(o.hist={}))[o.i+"_"+o.qi]=i;o.tot++;if(i===qd[2]){o.score++;addXP(3)}else save();render()}
function rdNext(){const o=EX.rd,p=RD[o.order[o.i]];o.picked=null;
  if(o.qi<p.qs.length-1)o.qi++;else if(o.i<o.order.length-1){o.i++;o.qi=0}else{o.phase="done";EXADD({t:"read",s:o.score,n:o.tot})}
  if(o.phase!=="done"){const h=(o.hist||{})[o.i+"_"+o.qi];o.picked=h===undefined?null:h}
  render()}
function rdPrev(){const o=EX.rd;if(o.qi>0)o.qi--;else if(o.i>0){o.i--;o.qi=RD[o.order[o.i]].qs.length-1}else return;const h=(o.hist||{})[o.i+"_"+o.qi];o.picked=h===undefined?null:h;render()}
function speakLines(sc,rate,only){
  if(!("speechSynthesis" in window)){toast("Your browser has no speech. Use Chrome, Edge or Safari.");return}
  try{
    speechSynthesis.cancel();
    const vs=speechSynthesis.getVoices().filter(v=>v.lang&&v.lang.toLowerCase().startsWith("ja"));
    sc.forEach(([who,t],k)=>{if(only!==undefined&&only!==k)return;const u=new SpeechSynthesisUtterance(t);u.lang="ja-JP";u.rate=rate;
      u.pitch=who==="F"?1.25:.8;if(vs.length)u.voice=vs[(who==="F"?0:1)%vs.length];speechSynthesis.speak(u)});
  }catch(e){}
}
